INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSIKI.T1_MATAMSHI_BORA_SAUTI_.MATAMSHI', 'KISW.G5.KUSIKI.T1_MATAMSHI_BORA_SAUTI_', 'kiswahili', 5, 'Tofautisha sauti f/v, s/z, l/r na th/dh katika silabi, maneno na vitanzandimi', ARRAY['KISW.G5.KUSIKI.T1_MATAMSHI_BORA_SAUTI_.a', 'KISW.G5.KUSIKI.T1_MATAMSHI_BORA_SAUTI_.b', 'KISW.G5.KUSIKI.T1_MATAMSHI_BORA_SAUTI_.c', 'KISW.G5.KUSIKI.T1_MATAMSHI_BORA_SAUTI_.d']::text[], 'Hears, says and writes the right sound in syllables and words with f/v, s/z, l/r na th/dh (kula and kura, fua and vua), picks the word that matches the meaning, and tells a real kitanzandimi from an ordinary sentence, in 8 of 10 new items.', '["chagua neno ulilosikia","chagua maana ya neno","jaza pengo kwa neno sahihi","tambua kitanzandimi"]'::jsonb, '["recall","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI', 'KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU', 'kiswahili', 5, 'Elewa maana ya msamiati katika kifungu', ARRAY['KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.a', 'KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.b']::text[], 'Works out what a word means from the passage it is in, and picks the right word for a gap, and does not choose a look-alike word or a word from a nearby sentence, in 8 of 10 new items.', '["choose the meaning","fill the gap","spot the mistake"]'::jsonb, '["recall","infer"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI', 'KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU', 'kiswahili', 5, 'Elewa ujumbe, matukio na wahusika wa hadithi', ARRAY['KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.c', 'KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.d']::text[], 'Answers who, where, what happened and what the main message is from a short story, and puts events in order, without using outside knowledge or a detail from the wrong place, in 8 of 10 new questions.', '["choose the answer","type a short answer","put in order"]'::jsonb, '["recall","infer"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUANDI.T1_INSHA_YA_WASIFU.AINA_ZA_INSHA', 'KISW.G5.KUANDI.T1_INSHA_YA_WASIFU', 'kiswahili', 5, 'Tambua insha ya wasifu, masimulizi na maelezo', ARRAY['KISW.G5.KUANDI.T1_INSHA_YA_WASIFU.a', 'KISW.G5.KUANDI.T2_INSHA_YA_MASIMULIZI.a', 'KISW.G5.KUANDI.T5_INSHA_YA_MAELEZO.a', 'KISW.G5.KUANDI.T6_INSHA_YA_WASIFU.a', 'KISW.G5.KUANDI.T7_INSHA_YA_MAELEZO.a', 'KISW.G5.KUANDI.T8_INSHA_ZA_MASIMULIZI.a', 'KISW.G5.KUANDI.T9_INSHA_YA_MAELEZO.a', 'KISW.G5.KUANDI.T10_INSHA_YA_MASIMULIZI.a']::text[], 'Tells a short text that describes a person (wasifu), one that tells events in order (masimulizi) and one that explains how something is done or what it is (maelezo), in 8 of 10 new short texts.', '["choose the kind of text","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU', 'KISW.G5.KUANDI.T1_INSHA_YA_WASIFU', 'kiswahili', 5, 'Tambua na andika insha ya wasifu', ARRAY['KISW.G5.KUANDI.T1_INSHA_YA_WASIFU.b']::text[], 'Tells insha ya wasifu from other kinds of writing and its parts, and writes a description of a person, place or thing with describing words that agree with their nouns and no story of events; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.SARUFI.T1_AINA_ZA_NOMINO.PEKEE', 'KISW.G5.SARUFI.T1_AINA_ZA_NOMINO', 'kiswahili', 5, 'Tambua na tumia nomino za pekee', ARRAY['KISW.G5.SARUFI.T1_AINA_ZA_NOMINO.a', 'KISW.G5.SARUFI.T1_AINA_ZA_NOMINO.b']::text[], 'Picks the proper noun (the particular name of a person, place, river, school, month) from a sentence and uses one to fill a gap, and does not choose a common noun, a job title or the first word of the sentence, in 8 of 10 new sentences.', '["choose the proper noun","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.SARUFI.T1_AINA_ZA_NOMINO_2.KAWAIDA', 'KISW.G5.SARUFI.T1_AINA_ZA_NOMINO_2', 'kiswahili', 5, 'Tambua na tumia nomino za kawaida', ARRAY['KISW.G5.SARUFI.T1_AINA_ZA_NOMINO_2.a', 'KISW.G5.SARUFI.T1_AINA_ZA_NOMINO_2.b']::text[], 'Picks the common noun (the general name of a kind of person, place, animal or thing) from a sentence and uses one to fill a gap, and does not choose a name, a verb or an adjective, in 8 of 10 new sentences.', '["choose the common noun","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI_MIKTADHA', 'KISW.G5.KUSIKI.T2_MAAMKUZI_NA_MAAGANO', 'kiswahili', 5, 'Tumia maamkuzi na maagano yanayofaa muktadha', ARRAY['KISW.G5.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.a', 'KISW.G5.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.b', 'KISW.G5.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.c']::text[], 'Greets and takes leave in a way that fits the time of day, the person (elder, age-mate, a sick person, a stranger) and the setting (a hospital, a home, a journey), and gives the matching reply, in 8 of 10 new items.', '["chagua salamu ifaayo","chagua jibu la salamu","tambua kosa","igiza (mwalimu anasikiliza)"]'::jsonb, '["application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI', 'KISW.G5.KUSOMA.T2_KUSOMA_KWA_KINA', 'kiswahili', 5, 'Tumia mpangilio wa maneno katika kamusi', ARRAY['KISW.G5.KUSOMA.T2_KUSOMA_KWA_KINA.a', 'KISW.G5.KUSOMA.T2_KUSOMA_KWA_KINA.b']::text[], 'Puts words in dictionary (alphabetical) order, looking at the second and third letter when the first letters match, and finds the word that comes first or comes next, in 8 of 10 new lists.', '["choose the first word","choose the next word","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUANDI.T2_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'KISW.G5.KUANDI.T2_INSHA_YA_MASIMULIZI', 'kiswahili', 5, 'Tambua na andika insha ya masimulizi', ARRAY['KISW.G5.KUANDI.T2_INSHA_YA_MASIMULIZI.b']::text[], 'Tells insha ya masimulizi from other kinds of writing and its parts, and writes a story of events in the past tense, in order, with a title, an opening, a middle and a closing that gives the lesson; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.SARUFI.T2_AINA_ZA_NOMINO.WINGI', 'KISW.G5.SARUFI.T2_AINA_ZA_NOMINO', 'kiswahili', 5, 'Tambua na tumia nomino za wingi', ARRAY['KISW.G5.SARUFI.T2_AINA_ZA_NOMINO.a', 'KISW.G5.SARUFI.T2_AINA_ZA_NOMINO.b']::text[], 'Gives the plural of a noun in the classes ki-vi, m-wa, m-mi, ji-ma and n (kitabu-vitabu, mtoto-watoto, mti-miti, jiwe-mawe, kalamu-kalamu) and uses it in a sentence, without leaving the noun unchanged or putting on the wrong prefix, in 8 of 10 new items.', '["choose the plural","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.SARUFI.T2_AINA_ZA_NOMINO_2.VITENZI_JINA', 'KISW.G5.SARUFI.T2_AINA_ZA_NOMINO_2', 'kiswahili', 5, 'Tambua na tumia nomino za vitenzi-jina', ARRAY['KISW.G5.SARUFI.T2_AINA_ZA_NOMINO_2.a', 'KISW.G5.SARUFI.T2_AINA_ZA_NOMINO_2.b']::text[], 'Tells a verbal noun (kusoma, kucheza, kulima: the verb with ku- used as a noun) from an ordinary verb or the doer noun, and uses it in a sentence, in 8 of 10 new sentences.', '["choose the verbal noun","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSIKI.T3_VITENDAWILI.VITENDAWILI', 'KISW.G5.KUSIKI.T3_VITENDAWILI', 'kiswahili', 5, 'Tambua vitendawili', ARRAY['KISW.G5.KUSIKI.T3_VITENDAWILI.a', 'KISW.G5.KUSIKI.T3_VITENDAWILI.b']::text[], 'Picks the kitendawili (riddle) from a methali, a nahau and an ordinary sentence, and gives the answer to a known riddle, in 8 of 10 new items. Setting and guessing riddles aloud (outcome b) stays with the teacher.', '["choose the riddle","fill the gap"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE', 'KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA', 'kiswahili', 5, 'Tambua vipengele vya kusoma kwa ufasaha', ARRAY['KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.a', 'KISW.G5.KUSOMA.T11_KUSOMA_KWA_UFASAHA.a']::text[], 'Names what a fluent reader does (clear sounds, a fitting speed, a fitting voice, a pause at the koma and the kikomo) and does not take speed or loudness for fluency, in 8 of 10 new items. Reading a passage aloud at a fitting speed, with the voice and signs (outcomes c to e) is judged by a teacher listening.', '["choose the answer","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA', 'kiswahili', 5, 'Soma kifungu kwa sauti kwa matamshi bora, kasi ifaayo, sauti ifaayo na ishara', ARRAY['KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.b', 'KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.c', 'KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.d', 'KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.e']::text[], 'Reads a short passage aloud at a speaking pace, pauses at the koma and the kikomo, raises the voice for a question and shows feeling for an exclamation, says every sound clearly (no l for r), and uses a matching gesture, judged by the teacher with the KICD rubric; in the app picks the better reading of a line in 8 of 10 new items.', '["chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUANDI.T3_KUANDIKA_KWA_TARAKIL.SEHEMU_TARAKILISHI', 'KISW.G5.KUANDI.T3_KUANDIKA_KWA_TARAKIL', 'kiswahili', 5, 'Tambua sehemu za tarakilishi zinazotumika kupigia chapa', ARRAY['KISW.G5.KUANDI.T3_KUANDIKA_KWA_TARAKIL.a']::text[], 'Names the parts of a computer used to type (kibodi, kipanya, skrini, kitengo kikuu, kichapishi) and what each does, in 8 of 10 new items.', '["choose the part","fill the gap"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUANDI.T3_KUANDIKA_KWA_TARAKIL.CHAPA_TARAKILISHI', 'KISW.G5.KUANDI.T3_KUANDIKA_KWA_TARAKIL', 'kiswahili', 5, 'Chapa, hariri na uhifadhi kazi kwa tarakilishi', ARRAY['KISW.G5.KUANDI.T3_KUANDIKA_KWA_TARAKIL.b']::text[], 'Types a short text on the theme with correct spacing, capitals and punctuation, corrects mistakes with Backspace or by selecting, makes a word bold, and saves the work with a clear name in his folder, in 8 of 10 new items or tasks.', '["panga hatua","chagua kitufe au amri","tambua kosa","kazi ya vitendo (mwalimu anaangalia)"]'::jsonb, '["procedure"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.SARUFI.T3_AINA_ZA_NOMINO.MAKUNDI', 'KISW.G5.SARUFI.T3_AINA_ZA_NOMINO', 'kiswahili', 5, 'Tambua na tumia nomino za makundi', ARRAY['KISW.G5.SARUFI.T3_AINA_ZA_NOMINO.a', 'KISW.G5.SARUFI.T3_AINA_ZA_NOMINO.b']::text[], 'Names the usual group noun for people and things (umati wa watu, jeshi la askari, msafara wa magari, mkungu wa ndizi, tita la kuni) and does not use one group word for every group or a single noun, in 8 of 10 new sentences.', '["choose the group noun","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_2.AMBATA', 'KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_2', 'kiswahili', 5, 'Tambua na tumia nomino ambata', ARRAY['KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_2.a', 'KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_2.b']::text[], 'Tells a compound noun (mwanafunzi, mwanahabari, mwanamichezo: nouns built from two words joined into one) from a simple noun and uses one in a sentence, and does not write it as two separate words, in 8 of 10 new items.', '["choose the compound noun","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_3.DHAHANIA', 'KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_3', 'kiswahili', 5, 'Tambua, eleza na tumia nomino za dhahania', ARRAY['KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_3.a', 'KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_3.b', 'KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_3.c']::text[], 'Picks the abstract noun (upendo, ukarimu, amani, furaha, uongo: an idea or feeling that cannot be touched), gives it from the person or verb it comes from, and uses it in a sentence, without choosing a thing or a verb, in 8 of 10 new items.', '["choose the abstract noun","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.SARUFI.T3_UAKIFISHI.UAKIFISHI', 'KISW.G5.SARUFI.T3_UAKIFISHI', 'kiswahili', 5, 'Tambua na tumia herufi kubwa, koma, kikomo na kiulizi', ARRAY['KISW.G5.SARUFI.T3_UAKIFISHI.a', 'KISW.G5.SARUFI.T3_UAKIFISHI.b']::text[], 'Chooses the sentence with the right capital letter, koma, kikomo (full stop) and kiulizi (question mark), and finds the one mistake in a short note, in 8 of 10 new sentences.', '["choose the correct sentence","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSIKI.T4_MANENO_YA_HESHIMA_NA.HESHIMA', 'KISW.G5.KUSIKI.T4_MANENO_YA_HESHIMA_NA', 'kiswahili', 5, 'Tambua maneno ya heshima ya udugu', ARRAY['KISW.G5.KUSIKI.T4_MANENO_YA_HESHIMA_NA.a', 'KISW.G5.KUSIKI.T4_MANENO_YA_HESHIMA_NA.b']::text[], 'Names family relations and the greeting that shows respect (shangazi, mjomba, binamu, bibi, shikamoo, marahaba) and does not swap the mother''s side and the father''s side, in 8 of 10 new items. Using the words in daily talk (outcome b) stays with the teacher.', '["choose the word","fill the gap"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI', 'KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA', 'kiswahili', 5, 'Zingatia hatua za kiusalama unapotumia vifaa vya kidijitali', ARRAY['KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA.a', 'KISW.G5.KUSOMA.T10_MATINI_YA_KIDIJITALI.a']::text[], 'Chooses the safe step when using a phone, tablet or computer (keep the password secret, ask an adult before an unknown link, use a safe site) and not the unsafe one, in 8 of 10 new situations.', '["choose the safe step","spot the unsafe step"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI', 'KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA', 'kiswahili', 5, 'Fungua faili, sakura kwenye tovuti salama na usome matini ya kidijitali', ARRAY['KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA.b', 'KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA.c']::text[], 'Opens a saved file with the passage (finds the folder, double-clicks the file), searches a safe site with two or three key words, ignores pop-ups and adverts, and reads the passage for its message, in 8 of 10 new items or tasks.', '["chagua hatua sahihi","panga hatua","chagua maneno ya kutafutia","tambua kosa"]'::jsonb, '["procedure","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUANDI.T4_BARUAPEPE.BARUAPEPE', 'KISW.G5.KUANDI.T4_BARUAPEPE', 'kiswahili', 5, 'Tambua muundo wa baruapepe', ARRAY['KISW.G5.KUANDI.T4_BARUAPEPE.a', 'KISW.G5.KUANDI.T11_BARUAPEPE.a']::text[], 'Names the parts of an email (anayepokea, mada, salamu, ujumbe, hitimisho, jina la mwandishi) and puts the right words in the right part, in 8 of 10 new items.', '["choose the part","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUANDI.T4_BARUAPEPE.KUANDIKA_BARUAPEPE', 'KISW.G5.KUANDI.T4_BARUAPEPE', 'kiswahili', 5, 'Andika baruapepe kwa muundo na lugha ifaayo', ARRAY['KISW.G5.KUANDI.T4_BARUAPEPE.b']::text[], 'Tells baruapepe from other kinds of writing and its parts, and writes an email with the receiver''s address, a short subject, a greeting, the message in correct Kiswahili and a closing; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.SARUFI.T4_NGELI_YA_I_ZI.I_ZI', 'KISW.G5.SARUFI.T4_NGELI_YA_I_ZI', 'kiswahili', 5, 'Tumia ngeli ya I-ZI kwa upatanisho wa kisarufi', ARRAY['KISW.G5.SARUFI.T4_NGELI_YA_I_ZI.a', 'KISW.G5.SARUFI.T4_NGELI_YA_I_ZI.b', 'KISW.G5.SARUFI.T4_NGELI_YA_I_ZI.c']::text[], 'Knows nouns that belong to I-ZI (nyumba, meza, barabara, taa, simu), gives the subject prefix i- for one and zi- for many, and makes the plural of a sentence, in 8 of 10 new items.', '["choose the prefix","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSIKI.T5_METHALI.METHALI', 'KISW.G5.KUSIKI.T5_METHALI', 'kiswahili', 5, 'Tambua na eleza maana ya methali za bidii', ARRAY['KISW.G5.KUSIKI.T5_METHALI.a', 'KISW.G5.KUSIKI.T5_METHALI.b', 'KISW.G5.KUSIKI.T5_METHALI.c']::text[], 'Completes a methali about hard work (haba na haba hujaza kibaba) and says what it means, and does not read it word for word, in 8 of 10 new items. Using a methali when speaking (outcome c) stays with the teacher.', '["choose the meaning","fill the gap","spot the mistake"]'::jsonb, '["recall","infer"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI', 'KISW.G5.KUSOMA.T5_KUSOMA_KWA_UFAHAMU', 'kiswahili', 5, 'Tambua mizani na vina katika shairi', ARRAY['KISW.G5.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.a', 'KISW.G5.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.b']::text[], 'Counts the mizani (syllables) in a line by counting vowel sounds, and finds the vina (the matching endings of lines), and does not count words or letters, in 8 of 10 new lines.', '["count the mizani","choose the vina","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUANDI.T5_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'KISW.G5.KUANDI.T5_INSHA_YA_MAELEZO', 'kiswahili', 5, 'Tambua na andika insha ya maelezo', ARRAY['KISW.G5.KUANDI.T5_INSHA_YA_MAELEZO.b']::text[], 'Tells insha ya maelezo from other kinds of writing and its parts, and writes an explanation or description on the topic, in order, with detail that makes a picture and no point off the topic; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.SARUFI.T5_NGELI_YA_U_ZI.U_ZI', 'KISW.G5.SARUFI.T5_NGELI_YA_U_ZI', 'kiswahili', 5, 'Tumia ngeli ya U-ZI kwa upatanisho wa kisarufi', ARRAY['KISW.G5.SARUFI.T5_NGELI_YA_U_ZI.a', 'KISW.G5.SARUFI.T5_NGELI_YA_U_ZI.b', 'KISW.G5.SARUFI.T5_NGELI_YA_U_ZI.c']::text[], 'Knows nouns that belong to U-ZI (ukuta, wimbo, ubao, ufunguo, uso), gives u- for one and zi- for many, and gives the plural noun (ukuta-kuta, wimbo-nyimbo, ubao-mbao), in 8 of 10 new items.', '["choose the prefix","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSIKI.T6_USHAIRI.USHAIRI_MAADILI', 'KISW.G5.KUSIKI.T6_USHAIRI', 'kiswahili', 5, 'Kariri shairi, eleza msamiati wake na ujibu maswali ya ujumbe', ARRAY['KISW.G5.KUSIKI.T6_USHAIRI.a', 'KISW.G5.KUSIKI.T6_USHAIRI.b', 'KISW.G5.KUSIKI.T6_USHAIRI.c', 'KISW.G5.KUSIKI.T6_USHAIRI.d']::text[], 'Recites a short poem on good conduct with clear words and its beat, explains a word of the poem from its line, uses it in a sentence, and answers questions on the message from the poem only, in 8 of 10 new items (the recitation scored by the teacher).', '["chagua maana ya neno","jibu swali la ujumbe","chagua ukariri bora","kariri (mwalimu anasikiliza)"]'::jsonb, '["recall","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA_MAKTABA', 'KISW.G5.KUSOMA.T6_KUSOMA_KWA_KINA', 'kiswahili', 5, 'Chagua makala maktabani na uyasome kwa ufasaha', ARRAY['KISW.G5.KUSOMA.T6_KUSOMA_KWA_KINA.a', 'KISW.G5.KUSOMA.T6_KUSOMA_KWA_KINA.b']::text[], 'Finds an article in the library by its shelf and title (not by its picture), tells an article from a story or a poem, reads it with good pronunciation and pace, and gives its main point, in 8 of 10 new items.', '["chagua makala","tambua aina ya matini","chagua wazo kuu","soma (mwalimu anasikiliza)"]'::jsonb, '["evaluation","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU', 'KISW.G5.KUANDI.T6_INSHA_YA_WASIFU', 'kiswahili', 5, 'Tambua na andika insha ya wasifu', ARRAY['KISW.G5.KUANDI.T6_INSHA_YA_WASIFU.b']::text[], 'Tells insha ya wasifu from other kinds of writing and its parts, and writes a description of a person, place or thing with describing words that agree with their nouns and no story of events; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.SARUFI.T6_NGELI_YA_U_YA.U_YA', 'KISW.G5.SARUFI.T6_NGELI_YA_U_YA', 'kiswahili', 5, 'Tumia ngeli ya U-YA kwa upatanisho wa kisarufi', ARRAY['KISW.G5.SARUFI.T6_NGELI_YA_U_YA.a', 'KISW.G5.SARUFI.T6_NGELI_YA_U_YA.b', 'KISW.G5.SARUFI.T6_NGELI_YA_U_YA.c']::text[], 'Knows nouns that belong to U-YA (ugonjwa, unyoya, uchungu), gives u- for one and ya- for many, and gives the plural with ma-, in 8 of 10 new items.', '["choose the prefix","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSIKI.T7_NAHAU.NAHAU', 'KISW.G5.KUSIKI.T7_NAHAU', 'kiswahili', 5, 'Tambua na eleza maana ya nahau', ARRAY['KISW.G5.KUSIKI.T7_NAHAU.a', 'KISW.G5.KUSIKI.T7_NAHAU.b', 'KISW.G5.KUSIKI.T7_NAHAU.c']::text[], 'Completes a nahau (kukata tamaa, kupiga moyo konde, kula chumvi) and says what it means, and does not read it word for word, in 8 of 10 new items. Using a nahau when speaking (outcome c) stays with the teacher.', '["choose the meaning","fill the gap","spot the mistake"]'::jsonb, '["recall","infer"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'KISW.G5.KUSOMA.T7_KUSOMA_KWA_MAPANA', 'kiswahili', 5, 'Chagua matini ya kusoma na ueleze ujumbe wake', ARRAY['KISW.G5.KUSOMA.T7_KUSOMA_KWA_MAPANA.a', 'KISW.G5.KUSOMA.T7_KUSOMA_KWA_MAPANA.b']::text[], 'Chooses a text that suits his reading level and interest from its title, blurb and first page (not from the cover alone), tells the kind of text (hadithi, shairi, makala, gazeti), says its message in one sentence, and works out a new word from the sentence around it, in 8 of 10 new items.', '["chagua matini ifaayo","chagua ujumbe","tambua aina ya matini","eleza maana ya neno"]'::jsonb, '["evaluation","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUANDI.T7_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'KISW.G5.KUANDI.T7_INSHA_YA_MAELEZO', 'kiswahili', 5, 'Tambua na andika insha ya maelezo', ARRAY['KISW.G5.KUANDI.T7_INSHA_YA_MAELEZO.b']::text[], 'Tells insha ya maelezo from other kinds of writing and its parts, and writes an explanation or description on the topic, in order, with detail that makes a picture and no point off the topic; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.SARUFI.T7_NGELI_YA_KU_KU.KU_KU', 'KISW.G5.SARUFI.T7_NGELI_YA_KU_KU', 'kiswahili', 5, 'Tumia ngeli ya KU-KU kwa upatanisho wa kisarufi', ARRAY['KISW.G5.SARUFI.T7_NGELI_YA_KU_KU.a', 'KISW.G5.SARUFI.T7_NGELI_YA_KU_KU.b', 'KISW.G5.SARUFI.T7_NGELI_YA_KU_KU.c']::text[], 'Knows that a verbal noun (kusoma, kucheza, kula) is in KU-KU, takes ku- as its subject prefix, and has no plural, and does not agree it with a- or u-, in 8 of 10 new items.', '["choose the prefix","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSIKI.T8_VISAWE.VISAWE', 'KISW.G5.KUSIKI.T8_VISAWE', 'kiswahili', 5, 'Tambua visawe', ARRAY['KISW.G5.KUSIKI.T8_VISAWE.a', 'KISW.G5.KUSIKI.T8_VISAWE.b']::text[], 'Picks the word with almost the same meaning (furaha-bashasha, haraka-upesi) and does not pick the opposite, a related word or a look-alike, in 8 of 10 new items.', '["choose the word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO', 'KISW.G5.KUSOMA.T8_KUSOMA_KWA_UFAHAMU', 'kiswahili', 5, 'Tambua na elewa mchezo wa kuigiza', ARRAY['KISW.G5.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.a', 'KISW.G5.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.c', 'KISW.G5.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.d', 'KISW.G5.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.b', 'KISW.G5.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.e']::text[], 'Tells a play from a story (names of speakers, words spoken, directions in brackets), says what a word in the play means, and answers questions about it, in 8 of 10 new items.', '["choose the answer","type a short answer","identify the part"]'::jsonb, '["recall","infer"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUANDI.T8_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI', 'KISW.G5.KUANDI.T8_INSHA_ZA_MASIMULIZI', 'kiswahili', 5, 'Tambua na andika insha ya masimulizi', ARRAY['KISW.G5.KUANDI.T8_INSHA_ZA_MASIMULIZI.b']::text[], 'Tells insha ya masimulizi from other kinds of writing and its parts, and writes a story of events in the past tense, in order, with a title, an opening, a middle and a closing that gives the lesson; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.SARUFI.T8_MNYAMBULIKO_WA_VITEN.MNYAMBULIKO', 'KISW.G5.SARUFI.T8_MNYAMBULIKO_WA_VITEN', 'kiswahili', 5, 'Tambua na tumia kauli za kutendewa, kutendeka na kutendana', ARRAY['KISW.G5.SARUFI.T8_MNYAMBULIKO_WA_VITEN.a', 'KISW.G5.SARUFI.T8_MNYAMBULIKO_WA_VITEN.b']::text[], 'Tells the three verb forms apart (kutendewa: done for or to someone, kutendeka: can be done or becomes done, kutendana: done to each other) and picks the one a sentence needs, in 8 of 10 new items.', '["choose the verb form","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.LUGHA_RASMI', 'KISW.G5.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT', 'kiswahili', 5, 'Tambua miktadha rasmi na utumie lugha rasmi', ARRAY['KISW.G5.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.a', 'KISW.G5.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.b']::text[], 'Tells official settings (a clinic, a school office, a chief''s office, assembly) from informal ones, and speaks there in polite, standard Kiswahili with the right title (Daktari, Mwalimu Mkuu, Chifu), in 8 of 10 new items.', '["chagua muktadha rasmi","chagua sentensi rasmi","tambua kosa la lugha","igiza (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'KISW.G5.KUSOMA.T9_KUSOMA_KWA_MAPANA', 'kiswahili', 5, 'Chagua matini ya kusoma na ueleze ujumbe wake', ARRAY['KISW.G5.KUSOMA.T9_KUSOMA_KWA_MAPANA.a', 'KISW.G5.KUSOMA.T9_KUSOMA_KWA_MAPANA.b']::text[], 'Chooses a text that suits his reading level and interest from its title, blurb and first page (not from the cover alone), tells the kind of text (hadithi, shairi, makala, gazeti), says its message in one sentence, and works out a new word from the sentence around it, in 8 of 10 new items.', '["chagua matini ifaayo","chagua ujumbe","tambua aina ya matini","eleza maana ya neno"]'::jsonb, '["evaluation","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUANDI.T9_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'KISW.G5.KUANDI.T9_INSHA_YA_MAELEZO', 'kiswahili', 5, 'Tambua na andika insha ya maelezo', ARRAY['KISW.G5.KUANDI.T9_INSHA_YA_MAELEZO.b']::text[], 'Tells insha ya maelezo from other kinds of writing and its parts, and writes an explanation or description on the topic, in order, with detail that makes a picture and no point off the topic; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.SARUFI.T9_VINYUME_VYA_VITENZI.VINYUME', 'KISW.G5.SARUFI.T9_VINYUME_VYA_VITENZI', 'kiswahili', 5, 'Tambua na tumia vinyume vya vitenzi', ARRAY['KISW.G5.SARUFI.T9_VINYUME_VYA_VITENZI.a', 'KISW.G5.SARUFI.T9_VINYUME_VYA_VITENZI.b']::text[], 'Gives the true opposite of a verb (kufunga-kufungua, kuvaa-kuvua, kuingia-kutoka) and does not use a negative form or a word of similar meaning, in 8 of 10 new items.', '["choose the opposite","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSIKI.T10_TASHBIHI.TASHBIHI', 'KISW.G5.KUSIKI.T10_TASHBIHI', 'kiswahili', 5, 'Tambua na tumia tashbihi za tabia', ARRAY['KISW.G5.KUSIKI.T10_TASHBIHI.a', 'KISW.G5.KUSIKI.T10_TASHBIHI.b']::text[], 'Completes and picks a simile about behaviour (mkali kama simba, mwoga kama sungura) and does not leave out kama or take it word for word, in 8 of 10 new items.', '["choose the simile","fill the gap","spot the mistake"]'::jsonb, '["recall","infer"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSOMA.T10_MATINI_YA_KIDIJITALI.KUSOMA_KIDIJITALI', 'KISW.G5.KUSOMA.T10_MATINI_YA_KIDIJITALI', 'kiswahili', 5, 'Fungua faili, sakura kwenye tovuti salama na usome matini ya kidijitali', ARRAY['KISW.G5.KUSOMA.T10_MATINI_YA_KIDIJITALI.b', 'KISW.G5.KUSOMA.T10_MATINI_YA_KIDIJITALI.c', 'KISW.G5.KUSOMA.T10_MATINI_YA_KIDIJITALI.d']::text[], 'Opens a saved file with the passage (finds the folder, double-clicks the file), searches a safe site with two or three key words, ignores pop-ups and adverts, and reads the passage for its message, in 8 of 10 new items or tasks.', '["chagua hatua sahihi","panga hatua","chagua maneno ya kutafutia","tambua kosa"]'::jsonb, '["procedure","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUANDI.T10_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'KISW.G5.KUANDI.T10_INSHA_YA_MASIMULIZI', 'kiswahili', 5, 'Tambua na andika insha ya masimulizi', ARRAY['KISW.G5.KUANDI.T10_INSHA_YA_MASIMULIZI.b']::text[], 'Tells insha ya masimulizi from other kinds of writing and its parts, and writes a story of events in the past tense, in order, with a title, an opening, a middle and a closing that gives the lesson; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.SARUFI.T10_NYAKATI_NA_HALI.MAZOEA_TIMILIFU', 'KISW.G5.SARUFI.T10_NYAKATI_NA_HALI', 'kiswahili', 5, 'Tambua na tumia hali ya mazoea na hali timilifu', ARRAY['KISW.G5.SARUFI.T10_NYAKATI_NA_HALI.a', 'KISW.G5.SARUFI.T10_NYAKATI_NA_HALI.b', 'KISW.G5.SARUFI.T10_NYAKATI_NA_HALI.c']::text[], 'Uses hu- for what is done every day (Juma hunywa maji) with no subject prefix, and -me- for what is finished (amemaliza), and does not mix them with -na- or -li-, in 8 of 10 new items.', '["choose the verb","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSIKI.T11_MASIMULIZI.MASIMULIZI', 'KISW.G5.KUSIKI.T11_MASIMULIZI', 'kiswahili', 5, 'Sikiliza masimulizi kwa ujumbe na usimulie kwa ishara zifaazo', ARRAY['KISW.G5.KUSIKI.T11_MASIMULIZI.a', 'KISW.G5.KUSIKI.T11_MASIMULIZI.b', 'KISW.G5.KUSIKI.T11_MASIMULIZI.c']::text[], 'Listens to a short narration and gives its message (not a detail), retells it in order, and tells his own story on the topic in Kiswahili sanifu with gestures that match the words; the teacher scores the telling with the KICD rubric, and in the app the child picks the message, order or gesture in 8 of 10 new items.', '["chagua ujumbe","panga matukio uliyosikia","chagua ishara ifaayo","kusimulia (mwalimu anasikiliza)"]'::jsonb, '["listening","application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'KISW.G5.KUSOMA.T11_KUSOMA_KWA_UFASAHA', 'kiswahili', 5, 'Soma kifungu kwa sauti kwa matamshi bora, kasi ifaayo, sauti ifaayo na ishara', ARRAY['KISW.G5.KUSOMA.T11_KUSOMA_KWA_UFASAHA.b', 'KISW.G5.KUSOMA.T11_KUSOMA_KWA_UFASAHA.c', 'KISW.G5.KUSOMA.T11_KUSOMA_KWA_UFASAHA.d', 'KISW.G5.KUSOMA.T11_KUSOMA_KWA_UFASAHA.e']::text[], 'Reads a short passage aloud at a speaking pace, pauses at the koma and the kikomo, raises the voice for a question and shows feeling for an exclamation, says every sound clearly (no l for r), and uses a matching gesture, judged by the teacher with the KICD rubric; in the app picks the better reading of a line in 8 of 10 new items.', '["chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.KUANDI.T11_BARUAPEPE.KUANDIKA_BARUAPEPE', 'KISW.G5.KUANDI.T11_BARUAPEPE', 'kiswahili', 5, 'Andika baruapepe kwa muundo na lugha ifaayo', ARRAY['KISW.G5.KUANDI.T11_BARUAPEPE.b']::text[], 'Tells baruapepe from other kinds of writing and its parts, and writes an email with the receiver''s address, a short subject, a greeting, the message in correct Kiswahili and a closing; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.SARUFI.T11_UKANUSHAJI.UKANUSHAJI', 'KISW.G5.SARUFI.T11_UKANUSHAJI', 'kiswahili', 5, 'Kanusha viambishi vya nafsi na wakati', ARRAY['KISW.G5.SARUFI.T11_UKANUSHAJI.a', 'KISW.G5.SARUFI.T11_UKANUSHAJI.b', 'KISW.G5.SARUFI.T11_UKANUSHAJI.c']::text[], 'Makes the negative of a verb in the present (-na-), past (-li-), perfect (-me-) and future (-ta-) for the persons ni-, u-, a-, tu-, m-, wa-, and does not only add si or keep the tense marker, in 8 of 10 new items.', '["choose the negative","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.UKUBWA_M', 'KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N', 'kiswahili', 5, 'Badilisha nomino za m- kuwa ukubwa na udogo', ARRAY['KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.a', 'KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.b', 'KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.c', 'KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.d']::text[], 'Gives the big form (ji-) and the small form (ki-) of nouns that begin with m- (mtoto: jitoto, kitoto; mti: jiti, kijiti; mji: jiji, kijiji), and uses them in a sentence, in 8 of 10 new items.', '["choose the form","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.UKUBWA_N', 'KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2', 'kiswahili', 5, 'Badilisha nomino za n- kuwa ukubwa na udogo', ARRAY['KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.a', 'KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.b', 'KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.c', 'KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.d']::text[], 'Gives the big form and the small form of nouns that begin with n- (nyumba: jumba, kijumba; mbwa: jibwa, kibwa), and uses them in a sentence, in 8 of 10 new items.', '["choose the form","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
