INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.UKUBWA_N', 'KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.UKUBWA_M', 'skill', 'essential', 'Proposed: this skill builds on it. To confirm by a native Kiswahili teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.UKUBWA_N', 'KISW.G4.SARUFI.T11_UDOGO_WA_NOMINO.UDOGO', 'skill', 'essential', 'The small form with ki- was first met with m- nouns in Grade 4.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T1_MATAMSHI_BORA_SAUTI_.MATAMSHI.M5_MAT_SWAP_T1', 'KISW.G5.KUSIKI.T1_MATAMSHI_BORA_SAUTI_.MATAMSHI', 'Hears or says /r/ for /l/, so kula (to eat) becomes kura (a vote).', '{"question":"Mwalimu anasema: \"kula\". Umesikia neno lipi?","wrong_answer":"kura","correct_answer":"kula"}'::jsonb, 'Kikuyu has no /l/ and several Kenyan languages do not separate l/r, f/v, s/z or th/dh (dh is often said as z: zahabu for dhahabu), so the child hears and writes one sound for both.', 'The question "Mwalimu anasema: "kula". Umesikia neno lipi?" with "kura" among the options.', 'Say the pair slowly with a hand on the throat (or watching the lips); the child says which word was heard before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T1_MATAMSHI_BORA_SAUTI_.MATAMSHI.M5_MAT_SPELL_T1', 'KISW.G5.KUSIKI.T1_MATAMSHI_BORA_SAUTI_.MATAMSHI', 'Writes the word with the letter of the other sound (vua where fua is meant).', '{"question":"Jaza pengo: ___ maana yake ni \"to wash clothes\".","wrong_answer":"vua","correct_answer":"fua"}'::jsonb, 'The child spells as he speaks; if the two sounds are one sound in his speech, the letter is a guess.', 'The question "Jaza pengo: ___ maana yake ni "to wash clothes"." with "vua" among the options.', 'Pair each spelling with its meaning on a card; the child sorts the cards by meaning, then by letter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T1_MATAMSHI_BORA_SAUTI_.MATAMSHI.M5_MAT_SAME_T1', 'KISW.G5.KUSIKI.T1_MATAMSHI_BORA_SAUTI_.MATAMSHI', 'Thinks the two words are one word said in two ways, with one meaning.', '{"question":"\"fua\" na \"vua\" ni maneno yenye maana moja?","wrong_answer":"ndiyo","correct_answer":"hapana"}'::jsonb, 'The child has heard both said by different people for the same thing and takes the difference for an accent.', 'The question ""fua" na "vua" ni maneno yenye maana moja?" with "ndiyo" among the options.', 'Use both words in two sentences that cannot swap: the child says which sentence breaks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T1_MATAMSHI_BORA_SAUTI_.MATAMSHI.M5_MAT_TWISTER_T1', 'KISW.G5.KUSIKI.T1_MATAMSHI_BORA_SAUTI_.MATAMSHI', 'Takes any long sentence for a kitanzandimi, though it does not repeat the target sounds.', '{"question":"Ni kipi ni kitanzandimi?","wrong_answer":"Mama alipika wali na maharagwe jana.","correct_answer":"Fatuma alifua viatu vya Vivian vilivyofifia."}'::jsonb, 'The child thinks a kitanzandimi is any sentence that is hard to say, not one built by repeating close sounds.', 'The question "Ni kipi ni kitanzandimi?" with "Mama alipika wali na maharagwe jana." among the options.', 'Underline the target sounds in the real kitanzandimi; count them; the ordinary sentence has few or none.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T1_MATAMSHI_BORA_SAUTI_.MATAMSHI.M5_MAT_SYLL_T1', 'KISW.G5.KUSIKI.T1_MATAMSHI_BORA_SAUTI_.MATAMSHI', 'Breaks the word into syllables at the wrong place, so the target sound is lost (ku-la read as two wrong parts).', '{"question":"Neno \"kula\" lina silabi zipi?","wrong_answer":"k-ula","correct_answer":"ku-la"}'::jsonb, 'In Kiswahili every syllable ends in a vowel, and a nasal with its consonant (nd, mb, nj, ng) starts one syllable; the child splits by letters, not by sound.', 'The question "Neno "kula" lina silabi zipi?" with "k-ula" among the options.', 'Clap the word: one clap per vowel; the nasal goes with the consonant after it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI.M_MSA_LOOKALIKE', 'KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI', 'Picks a word that looks or sounds like the word in the passage.', '{"question":"Katika kifungu, \"kuchemsha\" maana yake ni nini?","wrong_answer":"kuchemka kwa maji","correct_answer":"kupasha maji moto hadi yatokote"}'::jsonb, 'The child reads the first letters and not the meaning.', 'A word with a look-alike among the options.', 'Read the sentence around the word and think what is being done.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI.M_MSA_NEARBY', 'KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI', 'Picks a word from a nearby sentence that is not about this word.', '{"question":"Katika kifungu, \"kuchemsha\" maana yake ni nini?","wrong_answer":"kuchuma majani ya chai","correct_answer":"kupasha maji moto hadi yatokote"}'::jsonb, 'The child grabs the first thing the passage says.', 'An option taken from another sentence.', 'Go back to the exact sentence with the word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI.M_MSA_OPPOSITE', 'KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI', 'Picks the opposite of the word.', '{"question":"Katika kifungu, \"kuchemsha\" maana yake ni nini?","wrong_answer":"kupoza maji","correct_answer":"kupasha maji moto hadi yatokote"}'::jsonb, 'The child finds the idea and then reverses it.', 'An option with the opposite meaning.', 'Does the word mean the same thing as your choice?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI.M_UFA_WRONG_PERSON', 'KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI', 'Gives another character for who did it.', '{"question":"Nani alimsaidia Wanjiru?","wrong_answer":"mwalimu","correct_answer":"bibi yake"}'::jsonb, 'The child remembers several names and joins them.', 'A who-question with another character as an option.', 'Find the sentence with the action and see who did it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI.M_UFA_OUTSIDE', 'KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI', 'Answers from what the child knows, not from what the passage says.', '{"question":"Walipika chakula gani?","wrong_answer":"ugali","correct_answer":"mchele"}'::jsonb, 'The child answers a Kenyan child''s common meal rather than the one in the passage.', 'A question whose answer is not the usual one.', 'Underline the answer in the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI.M_UFA_DETAIL_AS_MAIN', 'KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI', 'Gives a small detail as the main message.', '{"question":"Ujumbe mkuu wa hadithi ni upi?","wrong_answer":"Wanjiru alikuwa na sufuria nyekundu.","correct_answer":"Kusaidiana kunafanya kazi iwe rahisi."}'::jsonb, 'The child chooses a sentence that is easy to find.', 'A main-message question with a detail as one option.', 'Ask "Hadithi nzima inatufundisha nini?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI.M_UFA_ORDER', 'KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI', 'Puts events in the order they are told in the question, not in the story.', '{"question":"Panga matukio kwa mpangilio.","wrong_answer":"D, A, C, B","correct_answer":"A, B, C, D"}'::jsonb, 'The child does not go back to the story.', 'Ordering four events from the story.', 'Find each event in the story and see which came first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI.M_UFA_DETAIL_MIX', 'KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI', 'Gives a detail from the passage that belongs to another part of the story.', '{"question":"Wanjiru alichemsha maji katika nini?","wrong_answer":"kikombe","correct_answer":"sufuria kubwa"}'::jsonb, 'The child remembers many details and joins the wrong ones.', 'A what-or-where question with another detail of the passage as an option.', 'Find the exact sentence with the action in the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI.M5_MSA_ENGLISH', 'KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI', 'Gives an English word as the meaning (kuchemsha = boil) instead of explaining in Kiswahili.', '{"question":"Katika kifungu, \"kukaanga\" maana yake ni nini?","wrong_answer":"fry","correct_answer":"kupika kwa mafuta motoni"}'::jsonb, 'The child translates in his head and writes what he thought.', 'The question "Katika kifungu, "kukaanga" maana yake ni nini?" with "fry" among the options.', 'Ask for the meaning in Kiswahili words, using the cooking picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T1_INSHA_YA_WASIFU.AINA_ZA_INSHA.M_INS_WASIFU_STORY', 'KISW.G5.KUANDI.T1_INSHA_YA_WASIFU.AINA_ZA_INSHA', 'Takes a text that describes a person (wasifu) for a story (masimulizi).', '{"question":"Kifungu kinaelezea sura, tabia na maisha ya mtu. Ni insha ya aina gani?","wrong_answer":"masimulizi","correct_answer":"wasifu"}'::jsonb, 'Both kinds can mention a person.', 'Short texts: one describing a person, one telling events.', 'Ask whether the text tells what happened in order, or tells who someone is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T1_INSHA_YA_WASIFU.AINA_ZA_INSHA.M_INS_MAELEZO_STORY', 'KISW.G5.KUANDI.T1_INSHA_YA_WASIFU.AINA_ZA_INSHA', 'Takes a text that explains how something is done (maelezo) for a story.', '{"question":"Kifungu kinaeleza hatua za kupika uji. Ni insha ya aina gani?","wrong_answer":"masimulizi","correct_answer":"maelezo"}'::jsonb, 'The child sees a sequence in both.', 'A recipe-like text and a story.', 'Ask whether the writer says "what happened" or "how to do it".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T1_INSHA_YA_WASIFU.AINA_ZA_INSHA.M_INS_STORY_WASIFU', 'KISW.G5.KUANDI.T1_INSHA_YA_WASIFU.AINA_ZA_INSHA', 'Takes a story of events for a description of a person.', '{"question":"Kifungu kinasimulia kilichotokea Jumamosi kijijini. Ni insha ya aina gani?","wrong_answer":"wasifu","correct_answer":"masimulizi"}'::jsonb, 'A story has a person in it.', 'A story about a person doing things.', 'Does the text tell events in order?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU.M5_INS_STORY_T1', 'KISW.G5.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU', 'Tells a story of what happened where the insha should describe the person, place or thing.', '{"question":"Ni sentensi ipi inafaa katika insha ya wasifu kuhusu \"Mpishi Hodari wa Kijiji Chetu\"?","wrong_answer":"Siku moja tulienda sokoni tukapotea.","correct_answer":"Mama Neema ni mfupi, mnene kiasi, na ana tabasamu pana kila wakati."}'::jsonb, 'Stories are the kind of writing the child has done most and he falls back on it.', 'The question "Ni sentensi ipi inafaa katika insha ya wasifu kuhusu "Mpishi Hodari wa Kijiji Chetu"?" with "Siku moja tulienda sokoni tukapotea." among the options.', 'Ask what the reader should know about the topic at the end: what it looks like, what it is for.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU.M5_INS_DETAIL_T1', 'KISW.G5.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU', 'Describes with empty words (kizuri sana, kibaya) and no detail that makes a picture.', '{"question":"Ni sentensi ipi inajenga picha dhahiri kuhusu \"Mpishi Hodari wa Kijiji Chetu\"?","wrong_answer":"Mama Neema ni mzuri sana.","correct_answer":"Mama Neema ni mfupi, mnene kiasi, na ana tabasamu pana kila wakati."}'::jsonb, 'The child knows the thing well and assumes the reader sees it too.', 'The question "Ni sentensi ipi inajenga picha dhahiri kuhusu "Mpishi Hodari wa Kijiji Chetu"?" with "Mama Neema ni mzuri sana." among the options.', 'Five senses chart: what do you see, hear, smell, touch, taste? Turn one row into a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU.M5_INS_AGREE_T1', 'KISW.G5.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU', 'Uses a describing word that does not agree with its noun (bendera mzuri, miti mrefu).', '{"question":"Ni sentensi ipi ni sahihi?","wrong_answer":"Ana vyakula mitamu.","correct_answer":"Ana vyakula vitamu."}'::jsonb, 'The child uses one form of the adjective (m-) for every noun, as he hears it for people.', 'The question "Ni sentensi ipi ni sahihi?" with "Ana vyakula mitamu." among the options.', 'Find the noun first, then its ngeli, then the prefix of the adjective.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU.M5_INS_OFFTOPIC_T1', 'KISW.G5.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU', 'Puts in points that are not about the title.', '{"question":"Katika insha ya wasifu yenye anwani \"Mpishi Hodari wa Kijiji Chetu\", ni sentensi ipi haifai?","wrong_answer":"Rafiki yangu ana baiskeli mpya ya rangi ya bluu.","correct_answer":"Mama Neema ni mfupi, mnene kiasi, na ana tabasamu pana kila wakati."}'::jsonb, 'The child adds whatever he remembers so the insha is long enough.', 'The question "Katika insha ya wasifu yenye anwani "Mpishi Hodari wa Kijiji Chetu", ni sentensi ipi haifai?" with "Rafiki yangu ana baiskeli mpya ya rangi ya bluu." among the options.', 'Read each sentence and ask: does it tell the reader about the title? Cross out the ones that do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU.M5_INS_PARAS_T1', 'KISW.G5.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU', 'Writes the whole insha as one paragraph with no utangulizi, kiini and hitimisho.', '{"question":"Insha \"Mpishi Hodari wa Kijiji Chetu\" ina sehemu zipi?","wrong_answer":"aya moja ndefu","correct_answer":"utangulizi, kiini (aya kadhaa) na hitimisho"}'::jsonb, 'The child writes until the space is full and has not planned the parts.', 'The question "Insha "Mpishi Hodari wa Kijiji Chetu" ina sehemu zipi?" with "aya moja ndefu" among the options.', 'Fold the page into three; one part in each; one idea per paragraph in the middle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T1_INSHA_YA_WASIFU.AINA_ZA_INSHA.M5_INS_LETTER', 'KISW.G5.KUANDI.T1_INSHA_YA_WASIFU.AINA_ZA_INSHA', 'Takes a letter or an email for an insha of masimulizi because it tells news.', '{"question":"Matini inayoanza \"Mpendwa rafiki yangu,\" na kuishia \"Ni mimi rafiki yako\" ni ya aina gani?","wrong_answer":"insha ya masimulizi","correct_answer":"barua ya kirafiki"}'::jsonb, 'Both tell what happened; the child looks at the content and not at the layout.', 'The question "Matini inayoanza "Mpendwa rafiki yangu," na kuishia "Ni mimi rafiki yako" ni ya aina gani?" with "insha ya masimulizi" among the options.', 'Look at the beginning and the end: an address and greeting mean a letter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T1_AINA_ZA_NOMINO.PEKEE.M_PEKEE_GENERAL', 'KISW.G5.SARUFI.T1_AINA_ZA_NOMINO.PEKEE', 'Picks the general name of the kind of thing (mto, nchi, mji) where the particular name (Tana, Kenya, Nairobi) is needed.', '{"question":"Mto ___ ni mrefu kuliko mito yote nchini Kenya.","wrong_answer":"maji","correct_answer":"Tana"}'::jsonb, 'The child knows the word is a noun but not that a proper noun is the one particular name.', 'A question with a name and a general noun as options.', 'Ask "Kuna mito mingi, mto huu unaitwa nani?" Names point to one only.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T1_AINA_ZA_NOMINO.PEKEE.M_PEKEE_ROLE', 'KISW.G5.SARUFI.T1_AINA_ZA_NOMINO.PEKEE', 'Takes a job or title (mwalimu, daktari, mkulima) as a proper noun because it names one person.', '{"question":"Mwalimu mkuu wetu anaitwa ___.","wrong_answer":"mwalimu","correct_answer":"Kamau"}'::jsonb, 'A title sounds like a name when one person holds it.', 'Options with a title and a given name.', 'Many people can be called mwalimu. A name belongs to one person.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T1_AINA_ZA_NOMINO.PEKEE.M_PEKEE_START', 'KISW.G5.SARUFI.T1_AINA_ZA_NOMINO.PEKEE', 'Picks the first word of the sentence only because it starts with a capital letter.', '{"question":"Mwalimu alimpa Wanjiru kitabu. Nomino ya pekee ni ipi?","wrong_answer":"Mwalimu","correct_answer":"Wanjiru"}'::jsonb, 'The child uses the capital letter as the only sign of a proper noun.', 'A sentence that starts with a common noun and has a name in the middle.', 'Every sentence starts with a capital. Ask which word is the name of one person or place.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T1_AINA_ZA_NOMINO.PEKEE.M5_PEKEE_LOWER', 'KISW.G5.SARUFI.T1_AINA_ZA_NOMINO.PEKEE', 'Writes a proper noun with a small letter in the middle of a sentence (tulienda nairobi).', '{"question":"Andika vizuri: Tulisafiri hadi nairobi.","wrong_answer":"Tulisafiri hadi nairobi.","correct_answer":"Tulisafiri hadi Nairobi."}'::jsonb, 'The child knows the capital at the start of a sentence but not that every proper noun takes one.', 'The question "Andika vizuri: Tulisafiri hadi nairobi." with "Tulisafiri hadi nairobi." among the options.', 'Circle every name of a person or place in a passage; each starts with a capital wherever it is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T1_AINA_ZA_NOMINO_2.KAWAIDA.M_KAWAIDA_NAME', 'KISW.G5.SARUFI.T1_AINA_ZA_NOMINO_2.KAWAIDA', 'Picks a name (Juma, Mombasa) when asked for the common noun.', '{"question":"Chagua nomino ya kawaida: \"Juma alienda Mombasa kwa basi.\"","wrong_answer":"Juma","correct_answer":"basi"}'::jsonb, 'The child looks for any noun and takes the first one.', 'A sentence with names and one common noun.', 'Ask which word could name many buses, not one named person or place.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T1_AINA_ZA_NOMINO_2.KAWAIDA.M_KAWAIDA_NOT_NOUN', 'KISW.G5.SARUFI.T1_AINA_ZA_NOMINO_2.KAWAIDA', 'Picks a verb or an adjective as the common noun.', '{"question":"Mtoto mdogo analia. Nomino ni ipi?","wrong_answer":"analia","correct_answer":"mtoto"}'::jsonb, 'The child has not yet fixed what a noun is: a name of a person, place, animal or thing.', 'Options that mix a noun, a verb and an adjective.', 'Ask "Ninaweza kusema huyu ni nani au hiki ni nini?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T1_AINA_ZA_NOMINO_2.KAWAIDA.M5_KAWAIDA_CAPITAL', 'KISW.G5.SARUFI.T1_AINA_ZA_NOMINO_2.KAWAIDA', 'Gives a common noun a capital letter because it is important (Tulinunua Sufuria mpya).', '{"question":"Ni sentensi ipi imeandikwa sawa?","wrong_answer":"Mama alinunua Sufuria mpya.","correct_answer":"Mama alinunua sufuria mpya."}'::jsonb, 'The child capitalises words he feels are important, as on posters.', 'The question "Ni sentensi ipi imeandikwa sawa?" with "Mama alinunua Sufuria mpya." among the options.', 'Ask: is it the name of one particular thing or of the kind? A kind gets a small letter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T1_AINA_ZA_NOMINO_2.KAWAIDA.M5_KAWAIDA_PRONOUN', 'KISW.G5.SARUFI.T1_AINA_ZA_NOMINO_2.KAWAIDA', 'Picks a pronoun (yeye, wao) as the common noun.', '{"question":"Ni nomino ya kawaida ipi katika: \"Yeye alipika wali\"?","wrong_answer":"Yeye","correct_answer":"wali"}'::jsonb, 'A pronoun stands in the place of a noun, so it looks like one.', 'The question "Ni nomino ya kawaida ipi katika: "Yeye alipika wali"?" with "Yeye" among the options.', 'Ask whether the word names a kind of thing or points to someone named before.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI_MIKTADHA.M5_MAA_SICK', 'KISW.G5.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI_MIKTADHA', 'Greets a sick person with an ordinary "Habari?" and answers "Nzuri" for him, with no word of sympathy (pole).', '{"question":"Unamtembelea rafiki aliyelazwa hospitalini. Unasema nini kwanza?","wrong_answer":"Habari yako? Nzuri sana!","correct_answer":"Pole sana rafiki yangu. Unaendeleaje?"}'::jsonb, 'The child uses the one greeting he uses everywhere.', 'The question "Unamtembelea rafiki aliyelazwa hospitalini. Unasema nini kwanza?" with "Habari yako? Nzuri sana!" among the options.', 'Role-play a hospital visit; list words for the sick: pole, ugua pole, Mungu akupe nafuu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI_MIKTADHA.M5_MAA_REPLY_MARAHABA', 'KISW.G5.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI_MIKTADHA', 'Says "Marahaba" as the greeting to an elder and "Shikamoo" as the reply.', '{"question":"Mtoto anamsalimu mzee. Mtoto anasema nini?","wrong_answer":"Marahaba","correct_answer":"Shikamoo"}'::jsonb, 'The two words are always heard together and the child does not know which side says which.', 'The question "Mtoto anamsalimu mzee. Mtoto anasema nini?" with "Marahaba" among the options.', 'Act it out: the younger always says Shikamoo; the elder answers Marahaba.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI_MIKTADHA.M5_MAA_TIME', 'KISW.G5.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI_MIKTADHA', 'Uses "Lala salama" or "Usiku mwema" when leaving in the morning, or "Habari za asubuhi" at night.', '{"question":"Unaondoka kwa jirani saa tatu asubuhi. Unaaga vipi?","wrong_answer":"Usiku mwema!","correct_answer":"Kwaheri, siku njema!"}'::jsonb, 'The farewells are memorised as a list, not tied to the time of day.', 'The question "Unaondoka kwa jirani saa tatu asubuhi. Unaaga vipi?" with "Usiku mwema!" among the options.', 'Put farewells on a clock face: asubuhi, mchana, jioni, usiku.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI_MIKTADHA.M5_MAA_ENGLISH', 'KISW.G5.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI_MIKTADHA', 'Greets with an English or Sheng word (Hi, Sasa, Niaje) where a Kiswahili greeting is asked.', '{"question":"Ni salamu ipi ya Kiswahili sanifu?","wrong_answer":"Niaje mzee?","correct_answer":"Hujambo mzee? / Shikamoo mzee."}'::jsonb, 'These are the greetings of the playground and the radio.', 'The question "Ni salamu ipi ya Kiswahili sanifu?" with "Niaje mzee?" among the options.', 'Sort greetings into sanifu and not; use only sanifu in class role plays.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI.M_KAM_LENGTH', 'KISW.G5.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI', 'Puts words in order of length, not alphabet.', '{"question":"Neno gani huja kwanza kwenye kamusi?","wrong_answer":"mti","correct_answer":"baba"}'::jsonb, 'The child looks for the shortest or the first-looking word.', 'Words of different lengths.', 'Say the alphabet and look at the first letter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI.M_KAM_FIRST_ONLY', 'KISW.G5.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI', 'Looks only at the first letter and picks any word with the same first letter.', '{"question":"Neno gani huja kwanza kwenye kamusi?","wrong_answer":"samaki","correct_answer":"sahani"}'::jsonb, 'The child stops at the first letter when two words begin the same.', 'Words that begin with the same letter.', 'When the first letters match, look at the second letter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI.M_KAM_REVERSE', 'KISW.G5.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI', 'Puts the end of the alphabet first.', '{"question":"Neno gani huja mwisho kwenye kamusi?","wrong_answer":"ndizi","correct_answer":"zeze"}'::jsonb, 'The child mixes first and last.', 'A question that asks for the last word.', 'A comes first and Z comes last.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI.M5_KAM_FORM', 'KISW.G5.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI', 'Looks up a word in the form it has in the passage (alikimbia) and does not find it, instead of its root (-kimbia / kimbia).', '{"question":"Unataka maana ya \"wanaosoma\". Utatafuta neno lipi kamusini?","wrong_answer":"wanaosoma","correct_answer":"soma"}'::jsonb, 'The child looks for exactly what is on the page.', 'The question "Unataka maana ya "wanaosoma". Utatafuta neno lipi kamusini?" with "wanaosoma" among the options.', 'Strip the prefixes and suffixes: wa-na-o-som-a -> soma; then look up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T2_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI.M5_INS_FACTS_T2', 'KISW.G5.KUANDI.T2_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'Writes facts or an explanation where a story of events is asked.', '{"question":"Ni sentensi ipi ni mwanzo wa insha ya masimulizi yenye anwani \"Siku Nilipomsaidia Majeruhi\"?","wrong_answer":"Huduma ya kwanza ni msaada unaotolewa kabla ya daktari kufika.","correct_answer":"Nilimwona mvulana ameanguka kutoka kwenye baiskeli."}'::jsonb, 'The child knows a lot about the topic and writes what he knows instead of telling what happened.', 'The question "Ni sentensi ipi ni mwanzo wa insha ya masimulizi yenye anwani "Siku Nilipomsaidia Majeruhi"?" with "Huduma ya kwanza ni msaada unaotolewa kabla ya daktari kufika." among the options.', 'Ask: who, where, what happened first, then, in the end? A story answers these; an explanation does not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T2_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI.M5_INS_TENSE_T2', 'KISW.G5.KUANDI.T2_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'Tells a past story in the present tense (-na-), or mixes -na- and -li- in one story.', '{"question":"Ni sentensi ipi inafaa katika masimulizi ya jambo lililotokea jana: \"Siku Nilipomsaidia Majeruhi\"?","wrong_answer":"Ninamwona mvulana ameanguka kutoka kwenye baiskeli.","correct_answer":"Nilimwona mvulana ameanguka kutoka kwenye baiskeli."}'::jsonb, 'The child writes as he speaks while remembering, and English stories in class are told in the present too.', 'The question "Ni sentensi ipi inafaa katika masimulizi ya jambo lililotokea jana: "Siku Nilipomsaidia Majeruhi"?" with "Ninamwona mvulana ameanguka kutoka kwenye baiskeli." among the options.', 'Circle every verb; check its tense marker against the time words (jana, siku moja).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T2_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI.M5_INS_ORDER_T2', 'KISW.G5.KUANDI.T2_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'Puts the events in an order that cannot have happened (the end before the start), with no linking words.', '{"question":"Ni mpangilio upi wa matukio unafaa katika insha \"Siku Nilipomsaidia Majeruhi\"?","wrong_answer":"nilimwita mwalimu, nilisafisha jeraha, nilimsaidia kuketi, niliona ajali","correct_answer":"niliona ajali, nilimsaidia kuketi, nilisafisha jeraha, nilimwita mwalimu"}'::jsonb, 'The child writes events as they come to mind; nobody has asked for a plan first.', 'The question "Ni mpangilio upi wa matukio unafaa katika insha "Siku Nilipomsaidia Majeruhi"?" with "nilimwita mwalimu, nilisafisha jeraha, nilimsaidia kuketi, niliona ajali" among the options.', 'Plan with three boxes (mwanzo, kati, mwisho) and linking words (kwanza, kisha, hatimaye) before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T2_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI.M5_INS_END_T2', 'KISW.G5.KUANDI.T2_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'Ends the insha abruptly ("Mwisho." or "The end") with no closing paragraph (hitimisho).', '{"question":"Ni ipi ni hitimisho bora la insha \"Siku Nilipomsaidia Majeruhi\"?","wrong_answer":"Mwisho.","correct_answer":"Tangu siku hiyo, nimejifunza kuwa mwangalifu kila wakati."}'::jsonb, 'Storybooks for young readers end with "Mwisho" and the child copies that.', 'The question "Ni ipi ni hitimisho bora la insha "Siku Nilipomsaidia Majeruhi"?" with "Mwisho." among the options.', 'Show three endings; the child picks the one that closes the main idea or the lesson.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T2_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI.M5_INS_MIX_T2', 'KISW.G5.KUANDI.T2_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'Puts English or Sheng words in the insha (tulienda kwa party, mathe, form).', '{"question":"Ni sentensi ipi imeandikwa kwa Kiswahili sanifu?","wrong_answer":"Mathe alinipea form ya kujaza.","correct_answer":"Mama alinipa fomu ya kujaza."}'::jsonb, 'The child speaks a mixed language at home and with friends and does not notice the switch in writing.', 'The question "Ni sentensi ipi imeandikwa kwa Kiswahili sanifu?" with "Mathe alinipea form ya kujaza." among the options.', 'Underline each non-Kiswahili word; find the Kiswahili word together (mama, sherehe, fomu).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T2_AINA_ZA_NOMINO.WINGI.M_WINGI_UNCHANGED', 'KISW.G5.SARUFI.T2_AINA_ZA_NOMINO.WINGI', 'Leaves the noun unchanged where the plural changes it (kitabu for vitabu).', '{"question":"Kitabu kimoja, vitabu viwili. Andika wingi wa \"kitabu\".","wrong_answer":"kitabu","correct_answer":"vitabu"}'::jsonb, 'In English most plural markers come at the end; here the prefix changes.', 'A plural gap where the singular is an option.', 'Ask which part of the word shows "many".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T2_AINA_ZA_NOMINO.WINGI.M_WINGI_WRONG_PREFIX', 'KISW.G5.SARUFI.T2_AINA_ZA_NOMINO.WINGI', 'Puts the wrong plural prefix on the noun (watabu for vitabu, vitoto for watoto).', '{"question":"Wingi wa \"mtoto\" ni ___.","wrong_answer":"vitoto","correct_answer":"watoto"}'::jsonb, 'The child learned one prefix and uses it for every noun.', 'Plurals from two classes in one question.', 'Ask "Mtoto ni mtu au kitu?" People take wa-, things like kitabu take vi-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T2_AINA_ZA_NOMINO.WINGI.M_WINGI_DOUBLE', 'KISW.G5.SARUFI.T2_AINA_ZA_NOMINO.WINGI', 'Adds a plural prefix to a plural form or doubles it (wawatoto, vivitabu).', '{"question":"Wingi wa \"mti\" ni ___.","wrong_answer":"mimiti","correct_answer":"miti"}'::jsonb, 'The child tries to be sure it is plural and adds the prefix twice.', 'A gap where a doubled form is an option.', 'Say the word aloud and ask if one prefix is not enough.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T2_AINA_ZA_NOMINO.WINGI.M5_WINGI_COUNT', 'KISW.G5.SARUFI.T2_AINA_ZA_NOMINO.WINGI', 'Treats a noun of wingi (maji, mafuta, maziwa) as countable and gives it a singular (jimaji, mamaji, maji moja).', '{"question":"Ni sentensi ipi ni sahihi?","wrong_answer":"Nimekunywa maji mawili.","correct_answer":"Nimekunywa maji mengi."}'::jsonb, 'Most nouns the child meets have a singular and a plural, so he looks for one here too.', 'The question "Ni sentensi ipi ni sahihi?" with "Nimekunywa maji mawili." among the options.', 'Pour water: you cannot count "one water"; you count glasses of it (glasi mbili za maji).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T2_AINA_ZA_NOMINO_2.VITENZI_JINA.M_VJ_NO_KU', 'KISW.G5.SARUFI.T2_AINA_ZA_NOMINO_2.VITENZI_JINA', 'Uses the bare verb stem (soma, cheza) where the verbal noun with ku- is needed.', '{"question":"___ kunafurahisha.","wrong_answer":"Soma","correct_answer":"Kusoma"}'::jsonb, 'The child reads the stem as the noun.', 'A gap with the stem and the ku- form as options.', 'Ask which word can start the sentence like a noun (it begins with ku-).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T2_AINA_ZA_NOMINO_2.VITENZI_JINA.M_VJ_CONJUGATED', 'KISW.G5.SARUFI.T2_AINA_ZA_NOMINO_2.VITENZI_JINA', 'Uses a conjugated verb (anasoma) as the verbal noun.', '{"question":"___ ni muhimu kwa kila mtoto.","wrong_answer":"Anasoma","correct_answer":"Kusoma"}'::jsonb, 'The child sees a verb and does not tell it apart from the verbal noun.', 'A conjugated verb among the options.', 'Ask whether the word says who is doing it and when.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T2_AINA_ZA_NOMINO_2.VITENZI_JINA.M_VJ_DOER', 'KISW.G5.SARUFI.T2_AINA_ZA_NOMINO_2.VITENZI_JINA', 'Uses the doer noun (msomaji, mkulima) for the action noun.', '{"question":"___ kunakuza akili.","wrong_answer":"Msomaji","correct_answer":"Kusoma"}'::jsonb, 'Both words come from the same verb and look alike.', 'The doer noun among the options.', 'Ask whether the gap names the action or the person who does it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T2_AINA_ZA_NOMINO_2.VITENZI_JINA.M5_VJ_AGREE', 'KISW.G5.SARUFI.T2_AINA_ZA_NOMINO_2.VITENZI_JINA', 'Gives a verbal noun the agreement of a person or a thing (kusoma anafurahisha, kusoma kinafurahisha) instead of ku-.', '{"question":"Jaza: Kusoma ___ (kunafurahisha / anafurahisha).","wrong_answer":"anafurahisha","correct_answer":"kunafurahisha"}'::jsonb, 'The child has not yet met KU-KU and copies the agreement he knows best.', 'The question "Jaza: Kusoma ___ (kunafurahisha / anafurahisha)." with "anafurahisha" among the options.', 'A verbal noun keeps ku- in the verb that follows: kusoma kunafurahisha.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T3_VITENDAWILI.VITENDAWILI.M_VIT_METHALI', 'KISW.G5.KUSIKI.T3_VITENDAWILI.VITENDAWILI', 'Takes a methali for a riddle.', '{"question":"Ni kitendawili kipi?","wrong_answer":"Haba na haba hujaza kibaba","correct_answer":"Nyumba yangu haina mlango"}'::jsonb, 'Both are short sayings.', 'A riddle and a methali.', 'A riddle asks a hidden question and waits for the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T3_VITENDAWILI.VITENDAWILI.M_VIT_NAHAU', 'KISW.G5.KUSIKI.T3_VITENDAWILI.VITENDAWILI', 'Takes a nahau for a riddle.', '{"question":"Ni kitendawili kipi?","wrong_answer":"Kukata tamaa","correct_answer":"Popote niendapo hunifuata"}'::jsonb, 'Both can be a short phrase.', 'A riddle and a nahau.', 'Can you guess an answer to it?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T3_VITENDAWILI.VITENDAWILI.M_VIT_PLAIN', 'KISW.G5.KUSIKI.T3_VITENDAWILI.VITENDAWILI', 'Takes an ordinary sentence for a riddle.', '{"question":"Ni kitendawili kipi?","wrong_answer":"Yai ni chakula kizuri","correct_answer":"Nyumba yangu haina mlango"}'::jsonb, 'The child does not see that a riddle hides the thing it describes.', 'A riddle and a plain sentence.', 'Does the text name the thing, or hide it?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T3_VITENDAWILI.VITENDAWILI.M_VIT_WRONG_ANSWER', 'KISW.G5.KUSIKI.T3_VITENDAWILI.VITENDAWILI', 'Gives a thing that shares one detail with the riddle but is not the answer.', '{"question":"\"Popote niendapo hunifuata.\" Jibu ni nini?","wrong_answer":"mbwa","correct_answer":"kivuli"}'::jsonb, 'The child picks the first thing that comes to mind.', 'A riddle with plausible answers.', 'Test each answer against every part of the riddle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE.M_UFS_SPEED', 'KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE', 'Takes fast reading for fluent reading, or very slow reading for careful reading.', '{"question":"Kasi ifaayo ya kusoma ni ipi?","wrong_answer":"Haraka iwezekanavyo","correct_answer":"Si haraka sana wala polepole sana"}'::jsonb, 'The child thinks the best reader is the fastest.', 'A question on speed with extremes as options.', 'Ask whether the listener can follow every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE.M_UFS_LOUD', 'KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE', 'Takes a loud voice for a fitting voice.', '{"question":"Sauti ipasavyo wakati wa kusoma ni ipi?","wrong_answer":"Kupiga kelele","correct_answer":"Sauti inayosikika wazi bila kupiga kelele"}'::jsonb, 'The child thinks louder is better.', 'A question on the voice with shouting and whispering as options.', 'Ask whether the voice is clear and comfortable to listen to.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE.M_UFS_IGNORE_MARKS', 'KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE', 'Reads on without a pause at the koma and the kikomo.', '{"question":"Ukifika kwenye koma wakati wa kusoma, ufanye nini?","wrong_answer":"Niendelee bila kupumzika","correct_answer":"Nipumzike kidogo"}'::jsonb, 'The child reads word after word and does not use the marks.', 'A question on the pause at a koma or a kikomo.', 'Read the sentence aloud and listen to where the voice rests.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M5_UFS_WORDBYWORD_T3', 'KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Bibi alivaa shanga nyekundu na bangili za fedha.\"?","wrong_answer":"Bibi ... alivaa ... shanga ... nyekundu ... na ... bangili ... za ... fedha.","correct_answer":"Bibi alivaa shanga nyekundu na bangili za fedha."}'::jsonb, 'The child is still decoding each word and has not yet learnt to read a phrase as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Bibi alivaa shanga nyekundu na bangili za fedha."?" with "Bibi ... alivaa ... shanga ... nyekundu ... na ... bangili ... za ... fedha." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it as one breath; then phrase-cut the passage with slashes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M5_UFS_RACE_T3', 'KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Ni kasi ipi ifaayo ya kusoma kifungu darasani?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, ili kila neno lisikike"}'::jsonb, 'Reading races in class reward speed; the child has not been asked whether listeners understood.', 'The question "Ni kasi ipi ifaayo ya kusoma kifungu darasani?" with "haraka iwezekanavyo" among the options.', 'Time two readings: one very fast, one at speaking pace; listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M5_UFS_FLAT_T3', 'KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads a question and an exclamation in the same flat voice as a statement.', '{"question":"Sentensi \"Je, umewahi kuvaa hereni za dhahabu?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the mark at the end.', 'The question "Sentensi "Je, umewahi kuvaa hereni za dhahabu?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that matches each reading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M5_UFS_NOPAUSE_T3', 'KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads on through the koma and the kikomo without a pause.', '{"question":"Unasoma: \"Lo, kanga yako inapendeza mno!\" Unasimama wapi kidogo?","wrong_answer":"hapana mahali, unasoma moja kwa moja","correct_answer":"kwenye koma na kwenye kikomo au alama ya hisi"}'::jsonb, 'The marks are read as decoration; the child has not linked them to breath.', 'The question "Unasoma: "Lo, kanga yako inapendeza mno!" Unasimama wapi kidogo?" with "hapana mahali, unasoma moja kwa moja" among the options.', 'Clap once at a koma, twice at a kikomo while reading together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M5_UFS_SOUND_T3', 'KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Says /l/ for /r/ or /r/ for /l/ while reading (hereni read as heleni).', '{"question":"Neno \"hereni\" linatamkwa vipi?","wrong_answer":"heleni","correct_answer":"hereni"}'::jsonb, 'The first language of the child does not separate these sounds, so the reading carries the home sound.', 'The question "Neno "hereni" linatamkwa vipi?" with "heleni" among the options.', 'Make a list of the passage words with the hard sound; practise them before reading the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE.M5_UFS_EYES', 'KISW.G5.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE', 'Thinks a fluent reader keeps his eyes on the book all the time.', '{"question":"Ni kipi ni kipengele cha kusoma kwa ufasaha?","wrong_answer":"kuangalia kitabu tu","correct_answer":"kuwaangalia wasikilizaji mara kwa mara"}'::jsonb, 'Reading has only been practised for accuracy.', 'The question "Ni kipi ni kipengele cha kusoma kwa ufasaha?" with "kuangalia kitabu tu" among the options.', 'Watch a news reader on TV: when does he look up?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T3_KUANDIKA_KWA_TARAKIL.SEHEMU_TARAKILISHI.M_TAR_MIX_PARTS', 'KISW.G5.KUANDI.T3_KUANDIKA_KWA_TARAKIL.SEHEMU_TARAKILISHI', 'Confuses the parts of the computer (kipanya for kibodi, skrini for kitengo kikuu).', '{"question":"Sehemu ya kupigia herufi ni ipi?","wrong_answer":"kipanya","correct_answer":"kibodi"}'::jsonb, 'The child has used the computer but does not know the names.', 'Names of the parts and what each does.', 'Which part has keys with letters?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T3_KUANDIKA_KWA_TARAKIL.SEHEMU_TARAKILISHI.M_TAR_FUNCTION', 'KISW.G5.KUANDI.T3_KUANDIKA_KWA_TARAKIL.SEHEMU_TARAKILISHI', 'Gives the wrong job for the part (kichapishi shows the screen).', '{"question":"Kichapishi hufanya nini?","wrong_answer":"Huonyesha maandishi","correct_answer":"Huchapisha maandishi kwenye karatasi"}'::jsonb, 'The child knows the word but not what it is for.', 'A part and its job.', 'A kichapishi prints on paper.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T3_KUANDIKA_KWA_TARAKIL.CHAPA_TARAKILISHI.M5_CHP_DELETE_ALL', 'KISW.G5.KUANDI.T3_KUANDIKA_KWA_TARAKIL.CHAPA_TARAKILISHI', 'Deletes the whole line or document to fix one wrong letter.', '{"question":"Umeandika \"mapambo\" kama \"mapanbo\". Utasahihisha vipi?","wrong_answer":"futa sentensi yote na uanze upya","correct_answer":"weka kishale baada ya \"n\", bonyeza Backspace, kisha andika \"m\""}'::jsonb, 'The child does not know the cursor can be placed anywhere.', 'The question "Umeandika "mapambo" kama "mapanbo". Utasahihisha vipi?" with "futa sentensi yote na uanze upya" among the options.', 'Practise moving the cursor with the mouse and the arrow keys before deleting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T3_KUANDIKA_KWA_TARAKIL.CHAPA_TARAKILISHI.M5_CHP_SAVE_AS', 'KISW.G5.KUANDI.T3_KUANDIKA_KWA_TARAKIL.CHAPA_TARAKILISHI', 'Saves over a classmate''s file or in a place he cannot find (the desktop of another user).', '{"question":"Unahifadhi insha yako. Ni wapi pafaa?","wrong_answer":"popote, kwa jina \"insha\"","correct_answer":"katika folda yako, kwa jina kama \"Mapambo - Wanjiku\""}'::jsonb, 'The child presses Save and accepts whatever the computer offers.', 'The question "Unahifadhi insha yako. Ni wapi pafaa?" with "popote, kwa jina "insha"" among the options.', 'Open the Save window together: choose the folder, type the name, then save.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T3_KUANDIKA_KWA_TARAKIL.CHAPA_TARAKILISHI.M5_CHP_BOLD', 'KISW.G5.KUANDI.T3_KUANDIKA_KWA_TARAKIL.CHAPA_TARAKILISHI', 'Tries to make a title bold by typing it again in capitals or with stars (*Mapambo*).', '{"question":"Unataka anwani \"MAPAMBO\" iwe na herufi nzito. Ufanye nini?","wrong_answer":"iandike mara mbili","correct_answer":"chagua anwani kisha bonyeza B (herufi nzito)"}'::jsonb, 'The child knows formatting from chat apps, where stars make bold.', 'The question "Unataka anwani "MAPAMBO" iwe na herufi nzito. Ufanye nini?" with "iandike mara mbili" among the options.', 'Select the word, then press the B button; watch it change.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T3_KUANDIKA_KWA_TARAKIL.CHAPA_TARAKILISHI.M5_CHP_SPACE_PUNCT', 'KISW.G5.KUANDI.T3_KUANDIKA_KWA_TARAKIL.CHAPA_TARAKILISHI', 'Types a space before the comma or full stop, and none after it (Shanga ,bangili .).', '{"question":"Ni ipi imechapwa sawa?","wrong_answer":"Shanga ,bangili na hereni .","correct_answer":"Shanga, bangili na hereni."}'::jsonb, 'On paper the gap is not seen; on screen the child presses space before every mark.', 'The question "Ni ipi imechapwa sawa?" with "Shanga ,bangili na hereni ." among the options.', 'Rule: the mark sticks to the word before it; the space comes after.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T3_KUANDIKA_KWA_TARAKIL.SEHEMU_TARAKILISHI.M5_TAR_KEYS', 'KISW.G5.KUANDI.T3_KUANDIKA_KWA_TARAKIL.SEHEMU_TARAKILISHI', 'Mixes the jobs of the special keys (Shift for a space, Enter for a capital).', '{"question":"Ni kitufe kipi hutumika kuandika herufi kubwa moja?","wrong_answer":"Enter","correct_answer":"Shift"}'::jsonb, 'The child has seen the keys but not used each for its job.', 'The question "Ni kitufe kipi hutumika kuandika herufi kubwa moja?" with "Enter" among the options.', 'Label the four special keys and practise each in a typing game.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T3_KUANDIKA_KWA_TARAKIL.SEHEMU_TARAKILISHI.M5_TAR_PRINTER', 'KISW.G5.KUANDI.T3_KUANDIKA_KWA_TARAKIL.SEHEMU_TARAKILISHI', 'Thinks the printer (kichapishi) shows the work and the screen prints it.', '{"question":"Kichapishi hufanya kazi gani?","wrong_answer":"huonyesha kazi","correct_answer":"hutoa nakala ya kazi kwenye karatasi"}'::jsonb, 'Both show the work; the child mixes which part shows and which prints.', 'The question "Kichapishi hufanya kazi gani?" with "huonyesha kazi" among the options.', 'Print one page in front of the class; compare with the screen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T3_AINA_ZA_NOMINO.MAKUNDI.M_MAK_WRONG_GROUP', 'KISW.G5.SARUFI.T3_AINA_ZA_NOMINO.MAKUNDI', 'Uses the group word of another group (jeshi for ndizi, umati for kuni).', '{"question":"Mama alinunua ___ wa ndizi sokoni.","wrong_answer":"umati","correct_answer":"mkungu"}'::jsonb, 'The child knows group words but not which one goes with which thing.', 'Group nouns for people, vehicles and fruit in one question.', 'Ask "Kundi hili ni la nini?" and think of the usual word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T3_AINA_ZA_NOMINO.MAKUNDI.M_MAK_SINGLE', 'KISW.G5.SARUFI.T3_AINA_ZA_NOMINO.MAKUNDI', 'Picks the name of one thing (mtu, gari, ndizi) where a group noun is needed.', '{"question":"Alipofika sokoni, aliona ___ wa watu wengi.","wrong_answer":"mtu","correct_answer":"umati"}'::jsonb, 'The child looks for a noun that fits the topic and does not see that a group is meant.', 'A single noun among the options.', 'Ask whether the gap names one or many.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T3_AINA_ZA_NOMINO.MAKUNDI.M5_MAK_PLURAL', 'KISW.G5.SARUFI.T3_AINA_ZA_NOMINO.MAKUNDI', 'Gives the plural of the thing (ndizi nyingi) where the group noun (chane la ndizi) is asked.', '{"question":"Ndizi nyingi zilizoshikana pamoja huitwa?","wrong_answer":"ndizi nyingi","correct_answer":"chane la ndizi"}'::jsonb, 'The child answers with the plural he already knows instead of the special group word.', 'The question "Ndizi nyingi zilizoshikana pamoja huitwa?" with "ndizi nyingi" among the options.', 'Pair the picture of the group with its word: chane la ndizi, kundi la ng''ombe, umati wa watu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T3_AINA_ZA_NOMINO.MAKUNDI.M5_MAK_AGREE', 'KISW.G5.SARUFI.T3_AINA_ZA_NOMINO.MAKUNDI', 'Agrees the verb with the things in the group, not with the group noun (kundi la ng''ombe wanakula).', '{"question":"Jaza: Kundi la ng''ombe ___ nyasi.","wrong_answer":"wanakula","correct_answer":"linakula"}'::jsonb, 'The child thinks of the cows, which are many, not of the word kundi.', 'The question "Jaza: Kundi la ng''ombe ___ nyasi." with "wanakula" among the options.', 'Find the head noun (kundi): the verb agrees with it, li- in LI-YA.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_2.AMBATA.M_AMBATA_SIMPLE', 'KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_2.AMBATA', 'Takes a long simple noun (mwalimu, daktari) for a compound noun.', '{"question":"Mtoto anayesoma shuleni ni ___.","wrong_answer":"mwalimu","correct_answer":"mwanafunzi"}'::jsonb, 'A long word looks as if it is built from parts.', 'Simple and compound nouns in one question.', 'Ask whether the word is two words joined, such as mwana + funzi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_2.AMBATA.M_AMBATA_SPLIT', 'KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_2.AMBATA', 'Writes a compound noun as two words (mwana funzi).', '{"question":"Mtoto anayesoma shuleni ni ___.","wrong_answer":"mwana funzi","correct_answer":"mwanafunzi"}'::jsonb, 'The child sees two parts and writes them apart, as in English.', 'A gap where a split form is an option.', 'Say it as one word and write it as one word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_2.AMBATA.M5_AMBATA_HYPHEN', 'KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_2.AMBATA', 'Adds a hyphen to a compound that is written as one word (mwana-funzi), or joins one that is written with a hyphen.', '{"question":"Ni ipi imeandikwa sawa?","wrong_answer":"mwana-funzi","correct_answer":"mwanafunzi"}'::jsonb, 'Hyphens are seen in some compounds (bata-mzinga) and the child adds them everywhere.', 'The question "Ni ipi imeandikwa sawa?" with "mwana-funzi" among the options.', 'Keep a list of compounds the way the dictionary writes them; check each new one there.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_2.AMBATA.M5_AMBATA_PHRASE', 'KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_2.AMBATA', 'Takes a noun with its describing word (nyumba kubwa) for a compound noun.', '{"question":"Ni ipi ni nomino ambata?","wrong_answer":"nyumba kubwa","correct_answer":"mwanasheria"}'::jsonb, 'Any two words together look like a compound.', 'The question "Ni ipi ni nomino ambata?" with "nyumba kubwa" among the options.', 'Ask whether the two words make one new name with its own meaning (mwanasheria is a lawyer, not a child of the law).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_3.DHAHANIA.M_DHA_CONCRETE', 'KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_3.DHAHANIA', 'Picks a thing that can be touched (mti, kitabu) as an abstract noun.', '{"question":"Nomino ya dhahania ni ipi?","wrong_answer":"kitabu","correct_answer":"upendo"}'::jsonb, 'The child has not fixed that an abstract noun is an idea or feeling you cannot touch.', 'A concrete noun and an abstract noun as options.', 'Ask "Ninaweza kuishika kwa mkono?" If yes, it is not dhahania.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_3.DHAHANIA.M_DHA_VERB', 'KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_3.DHAHANIA', 'Gives the verb (kupenda, kuwa mkarimu) where the abstract noun (upendo, ukarimu) is needed.', '{"question":"Mama ana moyo wa ___.","wrong_answer":"kupenda","correct_answer":"upendo"}'::jsonb, 'The verb and the noun come from the same idea.', 'A gap with a verb and its noun as options.', 'Ask which word can follow "wa" like a name of a feeling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_3.DHAHANIA.M_DHA_PERSON', 'KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_3.DHAHANIA', 'Gives the word for the person (mkarimu, mwongo) where the abstract noun (ukarimu, uongo) is needed.', '{"question":"Bibi yetu ana ___ mwingi.","wrong_answer":"mkarimu","correct_answer":"ukarimu"}'::jsonb, 'The child does not change m- (person) to u- (idea).', 'A gap where the person word and the idea word are options.', 'Ask "Ni mtu au ni tabia?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_3.DHAHANIA.M5_DHA_FEELING_ADJ', 'KISW.G5.SARUFI.T3_AINA_ZA_NOMINO_3.DHAHANIA', 'Gives the describing word (mwenye furaha, mzuri) where the abstract noun (furaha, uzuri) is needed.', '{"question":"Jaza: ___ wake ulituvutia sote (zuri).","wrong_answer":"Mzuri","correct_answer":"Uzuri"}'::jsonb, 'The adjective is the form the child uses most.', 'The question "Jaza: ___ wake ulituvutia sote (zuri)." with "Mzuri" among the options.', 'Change the m- of the adjective to u- to make the idea: mzuri -> uzuri, mrefu -> urefu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T3_UAKIFISHI.UAKIFISHI.M_UAK_NO_CAPITAL', 'KISW.G5.SARUFI.T3_UAKIFISHI.UAKIFISHI', 'Starts a sentence or a name with a small letter.', '{"question":"Chagua sentensi sahihi.","wrong_answer":"wanjiru alienda sokoni.","correct_answer":"Wanjiru alienda sokoni."}'::jsonb, 'Carelessness in a hurried hand or on a phone, or not seeing a name as a name.', 'Two sentences that differ only in the capital letter.', 'Look at the first letter of the sentence and of every name.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T3_UAKIFISHI.UAKIFISHI.M_UAK_WRONG_MARK', 'KISW.G5.SARUFI.T3_UAKIFISHI.UAKIFISHI', 'Ends a question with a kikomo (.) or a statement with a kiulizi (?).', '{"question":"Chagua sentensi sahihi.","wrong_answer":"Unaenda wapi.","correct_answer":"Unaenda wapi?"}'::jsonb, 'The child does not read the sentence as a question.', 'A question ended with a full stop and with a question mark.', 'Say it aloud: does your voice go up as if you ask?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T3_UAKIFISHI.UAKIFISHI.M_UAK_NO_COMMA', 'KISW.G5.SARUFI.T3_UAKIFISHI.UAKIFISHI', 'Leaves out the koma between things in a list or after a greeting word.', '{"question":"Chagua sentensi sahihi.","wrong_answer":"Mama alinunua mchele sukari na chumvi.","correct_answer":"Mama alinunua mchele, sukari na chumvi."}'::jsonb, 'The child writes as he speaks, without the pause.', 'A list written with and without koma.', 'Where would you pause when you read the list aloud?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T3_UAKIFISHI.UAKIFISHI.M_UAK_CAPITAL_COMMON', 'KISW.G5.SARUFI.T3_UAKIFISHI.UAKIFISHI', 'Writes a common noun in the middle of a sentence with a capital letter.', '{"question":"Chagua sentensi sahihi.","wrong_answer":"Tulienda Shule asubuhi.","correct_answer":"Tulienda shuleni asubuhi."}'::jsonb, 'Habit from English headings or from names.', 'A sentence with a capital on a common noun.', 'Ask whether the word is the name of one person or place.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T4_MANENO_YA_HESHIMA_NA.HESHIMA.M_HES_SIDE', 'KISW.G5.KUSIKI.T4_MANENO_YA_HESHIMA_NA.HESHIMA', 'Swaps the father''s side and the mother''s side (shangazi and mjomba).', '{"question":"Dada ya baba yako anaitwaje?","wrong_answer":"mjomba","correct_answer":"shangazi"}'::jsonb, 'The child knows the words but not the sides.', 'Relations from the father''s and the mother''s sides.', 'Shangazi is a woman (the father''s sister); mjomba is a man (the mother''s brother).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T4_MANENO_YA_HESHIMA_NA.HESHIMA.M_HES_GREETING', 'KISW.G5.KUSIKI.T4_MANENO_YA_HESHIMA_NA.HESHIMA', 'Swaps the greeting and the reply (shikamoo and marahaba).', '{"question":"Mtoto humsalimia babu kwa kusema ___.","wrong_answer":"marahaba","correct_answer":"shikamoo"}'::jsonb, 'The child knows both words but not who says which.', 'Greeting and reply asked in turn.', 'The younger person greets first; the elder replies.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T4_MANENO_YA_HESHIMA_NA.HESHIMA.M_HES_COUSIN', 'KISW.G5.KUSIKI.T4_MANENO_YA_HESHIMA_NA.HESHIMA', 'Calls a cousin kaka or dada (or ndugu), or the cousin''s parent mama.', '{"question":"Mtoto wa shangazi yako anaitwaje?","wrong_answer":"kaka","correct_answer":"binamu"}'::jsonb, 'The child uses the closest family word.', 'Relations beyond brothers and sisters.', 'A cousin is binamu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T4_MANENO_YA_HESHIMA_NA.HESHIMA.M5_HES_IN_LAW', 'KISW.G5.KUSIKI.T4_MANENO_YA_HESHIMA_NA.HESHIMA', 'Calls an in-law or a grandparent by the word for a parent (mama for mama mkwe, baba for babu).', '{"question":"Mama wa mke wa kaka yako unamwitaje?","wrong_answer":"mama","correct_answer":"mama mkwe (wa kaka)"}'::jsonb, 'The child uses the few kinship words he uses at home for every relative.', 'The question "Mama wa mke wa kaka yako unamwitaje?" with "mama" among the options.', 'Draw the family tree and label each place: babu, bibi, shangazi, mjomba, binamu, mkwe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI.M_DIG_SHARE', 'KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI', 'Shares a password or a personal detail with a friend or a stranger.', '{"question":"Ni hatua ipi ya kiusalama?","wrong_answer":"Kumpa rafiki nenosiri langu","correct_answer":"Kuweka nenosiri langu siri"}'::jsonb, 'The child thinks sharing is friendly.', 'Safe and unsafe steps for a password.', 'Ask who can use your account if they have the password.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI.M_DIG_LINK', 'KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI', 'Opens every link in a message from someone he does not know.', '{"question":"Ujumbe usiojulikana una kiungo cha zawadi. Ufanye nini?","wrong_answer":"Nikifungue haraka","correct_answer":"Nimwonyeshe mzazi au mwalimu kwanza"}'::jsonb, 'The child is curious and likes a prize.', 'An unknown message with a link.', 'Ask who sent it and whether you asked for it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI.M_DIG_UNSAFE_SITE', 'KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI', 'Searches on any site and gives details to a site that asks for them.', '{"question":"Unatafuta kifungu cha kusoma. Utumie tovuti ipi?","wrong_answer":"Tovuti inayotaka jina na nambari ya simu yangu","correct_answer":"Tovuti ya shule au maktaba iliyopendekezwa na mwalimu"}'::jsonb, 'The child does not ask who runs the site.', 'Safe and unsafe sites.', 'Ask whether the site needs your personal details to read.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI.M5_KID_FOLDER_T4', 'KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI', 'Mixes up a folder and a file: looks for the passage on the screen without opening the folder it is in.', '{"question":"Kifungu \"Majira ya Mwaka\" kimehifadhiwa ndani ya folda \"Kiswahili\". Utakifunguaje?","wrong_answer":"bonyeza \"Majira ya Mwaka\" kwenye skrini ya mwanzo","correct_answer":"fungua folda \"Kiswahili\", kisha bonyeza mara mbili faili \"Majira ya Mwaka\""}'::jsonb, 'The child has only used apps on a phone, where there are no folders.', 'The question "Kifungu "Majira ya Mwaka" kimehifadhiwa ndani ya folda "Kiswahili". Utakifunguaje?" with "bonyeza "Majira ya Mwaka" kwenye skrini ya mwanzo" among the options.', 'Show a real folder (a box file) holding papers; then the same on the screen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI.M5_KID_SEARCH_T4', 'KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI', 'Types a whole long question, with spelling mistakes, into the search box.', '{"question":"Unatafuta habari kuhusu saa na majira. Utaandika nini kwenye kisanduku cha kutafutia?","wrong_answer":"naomba unipe habari zote kuhusu saa na majira tafadhali","correct_answer":"majira mvua kiangazi Kenya"}'::jsonb, 'The child talks to the search box as to a person.', 'The question "Unatafuta habari kuhusu saa na majira. Utaandika nini kwenye kisanduku cha kutafutia?" with "naomba unipe habari zote kuhusu saa na majira tafadhali" among the options.', 'Underline the two or three words that carry the meaning; search with those; compare the results.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI.M5_KID_POPUP_T4', 'KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI', 'Clicks a pop-up or an advert that says he has won a prize.', '{"question":"Ukiwa unasoma, ujumbe unatokea: \"Umeshinda simu! Bonyeza hapa.\" Ufanye nini?","wrong_answer":"bonyeza ili kupokea simu","correct_answer":"usibonyeze; funga ujumbe na umwambie mwalimu au mzazi"}'::jsonb, 'Offers of prizes are exciting and the child does not know they are traps.', 'The question "Ukiwa unasoma, ujumbe unatokea: "Umeshinda simu! Bonyeza hapa." Ufanye nini?" with "bonyeza ili kupokea simu" among the options.', 'Show two screenshots, one real page and one trap; the child finds three signs of the trap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI.M5_KID_SITE_T4', 'KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI', 'Uses any site that comes up and gives his name, school or phone number when a site asks.', '{"question":"Tovuti inakuuliza jina lako kamili, shule yako na nambari ya simu ya mzazi kabla ya kusoma hadithi. Ufanye nini?","wrong_answer":"jaza ili usome hadithi","correct_answer":"usijaze; tumia tovuti salama aliyokupa mwalimu"}'::jsonb, 'The child wants the story and does not see personal details as worth protecting.', 'The question "Tovuti inakuuliza jina lako kamili, shule yako na nambari ya simu ya mzazi kabla ya kusoma hadithi. Ufanye nini?" with "jaza ili usome hadithi" among the options.', 'List the details that are private; practise saying no to a form.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI.M5_KID_ORDER_T4', 'KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI', 'Puts the steps of finding and reading a passage in the wrong order (reads before searching, or searches before switching on).', '{"question":"Ni hatua ipi huja kwanza?","wrong_answer":"andika maneno ya kutafutia","correct_answer":"washa tarakilishi na ufungue kivinjari"}'::jsonb, 'The child has watched an adult do the steps quickly and remembers the parts, not the order.', 'The question "Ni hatua ipi huja kwanza?" with "andika maneno ya kutafutia" among the options.', 'Step cards: the child orders them, then does them on a real device.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI.M5_DIG_TIME', 'KISW.G5.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI', 'Stays on a device for hours or uses it in the dark, close to the face.', '{"question":"Ni tabia ipi salama unapotumia kifaa cha kidijitali?","wrong_answer":"kukitumia gizani kwa saa nyingi","correct_answer":"kukitumia mahali penye mwanga kwa muda mfupi na kupumzika"}'::jsonb, 'Safety is taught as passwords and strangers only, not health.', 'The question "Ni tabia ipi salama unapotumia kifaa cha kidijitali?" with "kukitumia gizani kwa saa nyingi" among the options.', 'Set a timer in class; rest the eyes; sit straight.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T4_BARUAPEPE.BARUAPEPE.M_BAR_LETTER_FORM', 'KISW.G5.KUANDI.T4_BARUAPEPE.BARUAPEPE', 'Uses the layout of a friendly letter (address, date in the corner) for an email.', '{"question":"Anwani ya mpokeaji kwenye baruapepe huandikwa wapi?","wrong_answer":"Kona ya juu kulia","correct_answer":"Katika sehemu ya \"Kwa\""}'::jsonb, 'The child knows the letter layout and uses it for the email.', 'Layout of letter and email compared.', 'In an email, the address goes in a box at the top.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T4_BARUAPEPE.BARUAPEPE.M_BAR_NO_SUBJECT', 'KISW.G5.KUANDI.T4_BARUAPEPE.BARUAPEPE', 'Writes the message in the subject line, or leaves the subject empty.', '{"question":"Sehemu ya mada huandikwa nini?","wrong_answer":"Ujumbe wote","correct_answer":"Kichwa kifupi kinachosema ujumbe unahusu nini"}'::jsonb, 'The child does not see the subject as a title.', 'Subject and message mixed.', 'The subject is a short title, like a heading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T4_BARUAPEPE.BARUAPEPE.M_BAR_ORDER', 'KISW.G5.KUANDI.T4_BARUAPEPE.BARUAPEPE', 'Puts the greeting after the message or the name before the closing.', '{"question":"Baruapepe huisha na nini?","wrong_answer":"Salamu ya mwanzo","correct_answer":"Hitimisho na jina la mwandishi"}'::jsonb, 'The child does not know the usual order of the parts.', 'Parts of the email in a mixed order.', 'Salamu begins it; the name ends it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T4_BARUAPEPE.KUANDIKA_BARUAPEPE.M5_INS_NOSUBJ_T4', 'KISW.G5.KUANDI.T4_BARUAPEPE.KUANDIKA_BARUAPEPE', 'Leaves the subject box empty or writes the whole message in it.', '{"question":"Katika baruapepe, kisanduku cha \"Kichwa\" kinaandikwa nini?","wrong_answer":"ujumbe wote","correct_answer":"maneno machache yanayotaja ujumbe, kama \"Saa ya Mkutano wa Klabu\""}'::jsonb, 'The child has used chat apps that have no subject line.', 'The question "Katika baruapepe, kisanduku cha "Kichwa" kinaandikwa nini?" with "ujumbe wote" among the options.', 'Show an inbox: the subject is all the reader sees before opening.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T4_BARUAPEPE.KUANDIKA_BARUAPEPE.M5_INS_ADDR_T4', 'KISW.G5.KUANDI.T4_BARUAPEPE.KUANDIKA_BARUAPEPE', 'Writes a postal address and a date at the top, as in a paper letter.', '{"question":"Baruapepe huanza vipi?","wrong_answer":"S.L.P. 120, Nakuru, na tarehe juu kulia","correct_answer":"salamu kwa mpokeaji, kama \"Habari Amina,\""}'::jsonb, 'The paper letter is the model the child knows.', 'The question "Baruapepe huanza vipi?" with "S.L.P. 120, Nakuru, na tarehe juu kulia" among the options.', 'Compare a paper letter and an email; the email programme adds the address and date.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T4_BARUAPEPE.KUANDIKA_BARUAPEPE.M5_INS_TOFIELD_T4', 'KISW.G5.KUANDI.T4_BARUAPEPE.KUANDIKA_BARUAPEPE', 'Puts the receiver''s name, not the email address, in the "Kwa" box.', '{"question":"Kisanduku cha \"Kwa\" kinaandikwa nini?","wrong_answer":"Amina Otieno","correct_answer":"amina.otieno@mfano.co.ke"}'::jsonb, 'The child writes the person as on an envelope.', 'The question "Kisanduku cha "Kwa" kinaandikwa nini?" with "Amina Otieno" among the options.', 'Show what an email address looks like (jina@mahali); practise reading it aloud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T4_BARUAPEPE.KUANDIKA_BARUAPEPE.M5_INS_TEXTSPEAK_T4', 'KISW.G5.KUANDI.T4_BARUAPEPE.KUANDIKA_BARUAPEPE', 'Writes in short chat forms (sawa, poa, nkt, 2moro) and no closing.', '{"question":"Ni sentensi ipi inafaa katika baruapepe?","wrong_answer":"Poa, tutaonana 2moro.","correct_answer":"Asante. Tutaonana kesho."}'::jsonb, 'Chat habits come into the email.', 'The question "Ni sentensi ipi inafaa katika baruapepe?" with "Poa, tutaonana 2moro." among the options.', 'Rewrite one chat message as a short email with a greeting and a closing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T4_BARUAPEPE.BARUAPEPE.M5_BAR_ATTACH', 'KISW.G5.KUANDI.T4_BARUAPEPE.BARUAPEPE', 'Thinks a photo or file sent with the email (kiambatisho) is written in the message box.', '{"question":"Unataka kumtumia mwalimu picha ya kazi yako kwa baruapepe. Ufanye nini?","wrong_answer":"eleza picha kwenye ujumbe","correct_answer":"bonyeza alama ya kiambatisho na uchague picha"}'::jsonb, 'The child has not met attachments.', 'The question "Unataka kumtumia mwalimu picha ya kazi yako kwa baruapepe. Ufanye nini?" with "eleza picha kwenye ujumbe" among the options.', 'Show the paperclip button and send a test email with a picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T4_NGELI_YA_I_ZI.I_ZI.M_IZI_SG_ZI', 'KISW.G5.SARUFI.T4_NGELI_YA_I_ZI.I_ZI', 'Uses zi- with one noun of I-ZI.', '{"question":"Nyumba moja ___meanguka.","wrong_answer":"zi","correct_answer":"i"}'::jsonb, 'The child has fixed zi- as "the prefix of I-ZI" and does not tell one from many.', 'One and many in the same family of questions.', 'Count: is it one or many?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T4_NGELI_YA_I_ZI.I_ZI.M_IZI_PL_I', 'KISW.G5.SARUFI.T4_NGELI_YA_I_ZI.I_ZI', 'Uses i- with many nouns of I-ZI.', '{"question":"Nyumba nyingi ___meanguka.","wrong_answer":"i","correct_answer":"zi"}'::jsonb, 'The noun has the same form for one and many, so the child does not see that it is plural.', 'Plural nouns that look the same as the singular.', 'Look at the other words: nyingi, mbili. They say many.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T4_NGELI_YA_I_ZI.I_ZI.M_IZI_KI_VI', 'KISW.G5.SARUFI.T4_NGELI_YA_I_ZI.I_ZI', 'Uses ki-/vi- with a noun of I-ZI because it is a thing.', '{"question":"Meza mbili ___mevunjika.","wrong_answer":"vi","correct_answer":"zi"}'::jsonb, 'The child links "thing" with ki-vi and does not check the class.', 'A gap with the ki-vi prefixes as options.', 'Ask "Meza inapatana na kitabu au na nyumba?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T4_NGELI_YA_I_ZI.I_ZI.M_IZI_ADD_MA', 'KISW.G5.SARUFI.T4_NGELI_YA_I_ZI.I_ZI', 'Makes the plural of an I-ZI noun by adding ma- or a plural prefix (manyumba, mezazi).', '{"question":"Wingi wa \"Nyumba ni kubwa\" ni ___.","wrong_answer":"Manyumba ni makubwa.","correct_answer":"Nyumba ni kubwa."}'::jsonb, 'The child thinks every noun must change to show many.', 'Plural sentences with a changed noun and with an unchanged noun.', 'Ask whether this noun has a different plural form.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T5_METHALI.METHALI.M_MET_LITERAL', 'KISW.G5.KUSIKI.T5_METHALI.METHALI', 'Reads the methali word for word.', '{"question":"Mchumia juani hulia kivulini. Maana yake ni nini?","wrong_answer":"Anayekaa juani hulia","correct_answer":"Anayefanya kazi kwa bidii hufurahia matunda yake baadaye"}'::jsonb, 'The child does not know that a methali carries a second meaning.', 'A meaning question with a literal option.', 'Ask what lesson the methali teaches.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T5_METHALI.METHALI.M_MET_WRONG_LESSON', 'KISW.G5.KUSIKI.T5_METHALI.METHALI', 'Gives the lesson of another methali.', '{"question":"Haba na haba hujaza kibaba. Maana yake ni nini?","wrong_answer":"Umoja ni nguvu","correct_answer":"Vitu vidogo vikiongezwa polepole huwa vingi"}'::jsonb, 'The child knows methali but swaps their lessons.', 'The meaning of a different methali as an option.', 'Ask what the words say about little and little.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T5_METHALI.METHALI.M_MET_WRONG_END', 'KISW.G5.KUSIKI.T5_METHALI.METHALI', 'Completes the methali with a word that does not belong to it.', '{"question":"Haba na haba hujaza ___.","wrong_answer":"chupa","correct_answer":"kibaba"}'::jsonb, 'The child remembers the beginning but not the end.', 'A gap where a plausible wrong ending is an option.', 'Say the whole methali again from the beginning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T5_METHALI.METHALI.M5_MET_USE', 'KISW.G5.KUSIKI.T5_METHALI.METHALI', 'Uses a methali on hard work where its lesson does not fit the story (a lazy man rewarded).', '{"question":"Juma alilala badala ya kulima, mavuno yalipofika hakupata kitu. Methali ipi inafaa?","wrong_answer":"Haba na haba hujaza kibaba","correct_answer":"Mchagua jembe si mkulima"}'::jsonb, 'The child knows several methali on hard work and picks any of them.', 'The question "Juma alilala badala ya kulima, mavuno yalipofika hakupata kitu. Methali ipi inafaa?" with "Haba na haba hujaza kibaba" among the options.', 'Read the situation, say its lesson in one sentence, then find the methali with the same lesson.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI.M_SHA_COUNT_WORDS', 'KISW.G5.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI', 'Counts the words of the line, not the mizani.', '{"question":"Mshororo \"Mama anapika\" una mizani mingapi?","wrong_answer":"2","correct_answer":"6"}'::jsonb, 'The child counts what he can see.', 'A line with few words and many mizani.', 'Clap each sound: ma-ma-a-ni-pi-ka.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI.M_SHA_COUNT_LETTERS', 'KISW.G5.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI', 'Counts letters, not mizani.', '{"question":"Mshororo \"Nenda shule\" una mizani mingapi?","wrong_answer":"10","correct_answer":"5"}'::jsonb, 'The child counts the letters.', 'A line with an option equal to its letter count.', 'Count vowels: each vowel starts a new silabi in Kiswahili.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI.M_SHA_VINA_START', 'KISW.G5.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI', 'Looks at the start of the lines, not the end, to find vina.', '{"question":"Vina vya mishororo hii ni vipi?","wrong_answer":"ma-","correct_answer":"-ani"}'::jsonb, 'The child matches the beginnings.', 'Lines with matching endings only.', 'Vina are the endings that sound alike.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI.M_SHA_VINA_WORD', 'KISW.G5.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI', 'Says the whole last word must be the same for the lines to rhyme.', '{"question":"Mishororo \"shambani\" na \"nyumbani\" ina vina vipi?","wrong_answer":"hakuna","correct_answer":"-ani"}'::jsonb, 'The child thinks vina means the same word.', 'Two lines that end differently but with the same sound.', 'Say both endings aloud and listen to the last sounds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI.M_SHA_MISCOUNT', 'KISW.G5.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI', 'Miscounts the mizani by one, missing a vowel (the double vowel in bidii counted as one).', '{"question":"Mshororo \"Soma kwa bidii\" una mizani mingapi?","wrong_answer":"5","correct_answer":"6"}'::jsonb, 'The child counts "ii" or "ua" as one sound.', 'A line with a double vowel.', 'Clap each vowel: bi-di-i has three.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T5_INSHA_YA_MAELEZO.INSHA_MAELEZO.M5_INS_STORY_T5', 'KISW.G5.KUANDI.T5_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Tells a story of what happened where the insha should explain or describe.', '{"question":"Ni sentensi ipi inafaa katika insha ya maelezo kuhusu \"Jinsi ya Kupambana na Umaskini Nyumbani\"?","wrong_answer":"Siku moja tulienda sokoni tukapotea.","correct_answer":"Kwanza, tunapanda mboga kwenye kitalu kidogo nyuma ya nyumba."}'::jsonb, 'Stories are the kind of writing the child has done most and he falls back on it.', 'The question "Ni sentensi ipi inafaa katika insha ya maelezo kuhusu "Jinsi ya Kupambana na Umaskini Nyumbani"?" with "Siku moja tulienda sokoni tukapotea." among the options.', 'Ask what the reader should know about the topic at the end: what it is, how it works or is done.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T5_INSHA_YA_MAELEZO.INSHA_MAELEZO.M5_INS_DETAIL_T5', 'KISW.G5.KUANDI.T5_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Describes with empty words (kizuri sana, kibaya) and no detail that makes a picture.', '{"question":"Ni sentensi ipi inajenga picha dhahiri kuhusu \"Jinsi ya Kupambana na Umaskini Nyumbani\"?","wrong_answer":"Umaskini ni mbaya.","correct_answer":"Kwanza, tunapanda mboga kwenye kitalu kidogo nyuma ya nyumba."}'::jsonb, 'The child knows the thing well and assumes the reader sees it too.', 'The question "Ni sentensi ipi inajenga picha dhahiri kuhusu "Jinsi ya Kupambana na Umaskini Nyumbani"?" with "Umaskini ni mbaya." among the options.', 'Five senses chart: what do you see, hear, smell, touch, taste? Turn one row into a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T5_INSHA_YA_MAELEZO.INSHA_MAELEZO.M5_INS_STEPS_T5', 'KISW.G5.KUANDI.T5_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Gives the steps of how to do something in a mixed-up order.', '{"question":"Ni mpangilio upi unafaa katika maelezo ya \"Jinsi ya Kupambana na Umaskini Nyumbani\"?","wrong_answer":"weka akiba, uza ziada, panda mboga, panga bajeti","correct_answer":"panga bajeti, panda mboga, uza ziada, weka akiba"}'::jsonb, 'The child remembers the steps as a set, not as a sequence.', 'The question "Ni mpangilio upi unafaa katika maelezo ya "Jinsi ya Kupambana na Umaskini Nyumbani"?" with "weka akiba, uza ziada, panda mboga, panga bajeti" among the options.', 'Act out the steps; number them; write them with kwanza, kisha, mwishowe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T5_INSHA_YA_MAELEZO.INSHA_MAELEZO.M5_INS_OFFTOPIC_T5', 'KISW.G5.KUANDI.T5_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Puts in points that are not about the title.', '{"question":"Katika insha ya maelezo yenye anwani \"Jinsi ya Kupambana na Umaskini Nyumbani\", ni sentensi ipi haifai?","wrong_answer":"Rafiki yangu ana baiskeli mpya ya rangi ya bluu.","correct_answer":"Kwanza, tunapanda mboga kwenye kitalu kidogo nyuma ya nyumba."}'::jsonb, 'The child adds whatever he remembers so the insha is long enough.', 'The question "Katika insha ya maelezo yenye anwani "Jinsi ya Kupambana na Umaskini Nyumbani", ni sentensi ipi haifai?" with "Rafiki yangu ana baiskeli mpya ya rangi ya bluu." among the options.', 'Read each sentence and ask: does it tell the reader about the title? Cross out the ones that do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T5_INSHA_YA_MAELEZO.INSHA_MAELEZO.M5_INS_PARAS_T5', 'KISW.G5.KUANDI.T5_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Writes the whole insha as one paragraph with no utangulizi, kiini and hitimisho.', '{"question":"Insha \"Jinsi ya Kupambana na Umaskini Nyumbani\" ina sehemu zipi?","wrong_answer":"aya moja ndefu","correct_answer":"utangulizi, kiini (aya kadhaa) na hitimisho"}'::jsonb, 'The child writes until the space is full and has not planned the parts.', 'The question "Insha "Jinsi ya Kupambana na Umaskini Nyumbani" ina sehemu zipi?" with "aya moja ndefu" among the options.', 'Fold the page into three; one part in each; one idea per paragraph in the middle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T5_NGELI_YA_U_ZI.U_ZI.M_UZI_PL_MA', 'KISW.G5.SARUFI.T5_NGELI_YA_U_ZI.U_ZI', 'Puts ma- or mi- on the plural of a U-ZI noun (maukuta, mikuta).', '{"question":"Wingi wa \"ukuta\" ni ___.","wrong_answer":"mikuta","correct_answer":"kuta"}'::jsonb, 'The child changes u- to the prefixes he knows best.', 'Plural forms of nouns of U-ZI.', 'Ask whether you hear "mi" in a plural of ukuta in the house.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T5_NGELI_YA_U_ZI.U_ZI.M_UZI_AGR_I', 'KISW.G5.SARUFI.T5_NGELI_YA_U_ZI.U_ZI', 'Agrees a U-ZI noun with i- (as in U-I) instead of zi- in the plural.', '{"question":"Kuta mbili ___meanguka.","wrong_answer":"i","correct_answer":"zi"}'::jsonb, 'U-I and U-ZI both begin with u- in the singular.', 'A plural gap with i- and zi- as options.', 'Does the plural noun have mi- (like miti) or not?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T5_NGELI_YA_U_ZI.U_ZI.M_UZI_AGR_SG', 'KISW.G5.SARUFI.T5_NGELI_YA_U_ZI.U_ZI', 'Uses a wrong prefix (a-, ki- or i-) with a singular noun of U-ZI.', '{"question":"Ukuta ___meanguka.","wrong_answer":"i","correct_answer":"u"}'::jsonb, 'The child guesses a prefix from the sound of the noun.', 'A singular gap with u-, i-, a- and ki- as options.', 'Look at the first letter of the noun: it often gives the prefix.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T5_NGELI_YA_U_ZI.U_ZI.M5_UZI_PL_NOUN', 'KISW.G5.SARUFI.T5_NGELI_YA_U_ZI.U_ZI', 'Gives the wrong plural noun for a U-ZI noun (ukuta -> kuta is right; the child says ukuta -> mikuta or uta).', '{"question":"Wingi wa \"ukuta\" ni upi?","wrong_answer":"mikuta","correct_answer":"kuta"}'::jsonb, 'The plural of U-ZI drops u- and sometimes changes the stem (ufunguo -> funguo, ukuta -> kuta); the child adds a plural prefix he knows.', 'The question "Wingi wa "ukuta" ni upi?" with "mikuta" among the options.', 'List pairs: ufunguo/funguo, ukuta/kuta, uzi/nyuzi, ubao/mbao; say both forms aloud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T6_USHAIRI.USHAIRI_MAADILI.M5_USH_LINE_MESSAGE', 'KISW.G5.KUSIKI.T6_USHAIRI.USHAIRI_MAADILI', 'Gives one line of the poem, word for word, as its message.', '{"question":"Shairi linasema: \"Heshima ni kitu bora, tumheshimu kila mtu.\" Ujumbe wa shairi ni upi?","wrong_answer":"Heshima ni kitu bora","correct_answer":"tuwaheshimu watu wote ili tuishi vizuri"}'::jsonb, 'Copying a line feels safe; the child has not been asked to say the message in his own words.', 'The question "Shairi linasema: "Heshima ni kitu bora, tumheshimu kila mtu." Ujumbe wa shairi ni upi?" with "Heshima ni kitu bora" among the options.', 'After reading, close the poem and ask the child to say what the poet wants, without the poem''s words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T6_USHAIRI.USHAIRI_MAADILI.M5_USH_RECITE_FLAT', 'KISW.G5.KUSIKI.T6_USHAIRI.USHAIRI_MAADILI', 'Recites the whole poem in one flat tone and pace, with no beat and no pause between beti.', '{"question":"Unakariri shairi. Ni lipi ni bora?","wrong_answer":"kusoma maneno yote kwa kasi moja bila kusimama","correct_answer":"kufuata mahadhi ya shairi na kusimama kidogo baada ya kila ubeti"}'::jsonb, 'The child treats reciting as saying words from memory as fast as possible.', 'The question "Unakariri shairi. Ni lipi ni bora?" with "kusoma maneno yote kwa kasi moja bila kusimama" among the options.', 'Clap the mizani of one line; recite it with the claps; pause at the end of the ubeti.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T6_USHAIRI.USHAIRI_MAADILI.M5_USH_WORD_OUTSIDE', 'KISW.G5.KUSIKI.T6_USHAIRI.USHAIRI_MAADILI', 'Gives the everyday meaning of a word, not its meaning in the line (taji as a crown only, where the poem means honour).', '{"question":"\"Adabu ni taji la mtoto.\" Neno \"taji\" lina maana gani hapa?","wrong_answer":"kofia ya mfalme ya dhahabu","correct_answer":"heshima au fahari"}'::jsonb, 'The child knows one meaning of the word and does not test it against the line.', 'The question ""Adabu ni taji la mtoto." Neno "taji" lina maana gani hapa?" with "kofia ya mfalme ya dhahabu" among the options.', 'Read the line with each meaning in place; keep the one that makes sense.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T6_USHAIRI.USHAIRI_MAADILI.M5_USH_OUTSIDE', 'KISW.G5.KUSIKI.T6_USHAIRI.USHAIRI_MAADILI', 'Answers a question on the poem from what he thinks is right, not from what the poem says.', '{"question":"Kwa mujibu wa shairi, kwa nini tuwaheshimu wazee?","wrong_answer":"kwa sababu ni matajiri","correct_answer":"kwa sababu wana hekima na wametulea"}'::jsonb, 'The question sounds like a question about life, so the child answers from life.', 'The question "Kwa mujibu wa shairi, kwa nini tuwaheshimu wazee?" with "kwa sababu ni matajiri" among the options.', 'Ask for the line that gives the answer before accepting it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA_MAKTABA.M5_MAK_STORY', 'KISW.G5.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA_MAKTABA', 'Takes a story (with characters and events) for an article.', '{"question":"Ni ipi ni makala?","wrong_answer":"Hadithi ya Sungura na Fisi","correct_answer":"Faida za Kuwa Mwaminifu Shuleni"}'::jsonb, 'Both are read in the library and both have a title.', 'The question "Ni ipi ni makala?" with "Hadithi ya Sungura na Fisi" among the options.', 'Show the signs of an article: facts or advice on a topic, headings, no "Hapo zamani".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA_MAKTABA.M5_MAK_SHELF', 'KISW.G5.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA_MAKTABA', 'Looks for an article among the storybooks, or picks the first thing on the shelf.', '{"question":"Unatafuta makala kuhusu maadili maktabani. Utaanzia wapi?","wrong_answer":"kwenye rafu ya hadithi za watoto","correct_answer":"kwenye rafu ya magazeti na majarida au vitabu vya maarifa"}'::jsonb, 'The child has only used the storybook corner.', 'The question "Unatafuta makala kuhusu maadili maktabani. Utaanzia wapi?" with "kwenye rafu ya hadithi za watoto" among the options.', 'Walk the library: label shelves (hadithi, mashairi, maarifa, magazeti).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA_MAKTABA.M5_MAK_MAINPOINT', 'KISW.G5.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA_MAKTABA', 'Gives the example in the article (one boy returned a lost wallet) as its main point.', '{"question":"Wazo kuu la makala \"Faida za Uaminifu\" ni lipi?","wrong_answer":"Kijana mmoja alirudisha pochi iliyopotea.","correct_answer":"Uaminifu huleta heshima na imani kati ya watu."}'::jsonb, 'The example is a little story and is remembered; the child has not separated it from the point it supports.', 'The question "Wazo kuu la makala "Faida za Uaminifu" ni lipi?" with "Kijana mmoja alirudisha pochi iliyopotea." among the options.', 'Ask: is this the point, or an example that shows the point?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA_MAKTABA.M5_MAK_SKIM', 'KISW.G5.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA_MAKTABA', 'Reads only the title and the first line and answers from them.', '{"question":"Makala yana aya nne. Jibu la swali la tatu liko aya ya tatu. Ufanye nini?","wrong_answer":"jibu kutoka anwani","correct_answer":"soma aya zote, hasa aya ya tatu, kabla ya kujibu"}'::jsonb, 'The child wants to finish quickly and trusts the title.', 'The question "Makala yana aya nne. Jibu la swali la tatu liko aya ya tatu. Ufanye nini?" with "jibu kutoka anwani" among the options.', 'Number the paragraphs; for each question, find the paragraph first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU.M5_INS_STORY_T6', 'KISW.G5.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU', 'Tells a story of what happened where the insha should describe the person, place or thing.', '{"question":"Ni sentensi ipi inafaa katika insha ya wasifu kuhusu \"Mwalimu Wangu Mwadilifu\"?","wrong_answer":"Siku moja tulienda sokoni tukapotea.","correct_answer":"Mwalimu Achieng ni mrefu, mpole na husikiliza kila mwanafunzi kwa makini."}'::jsonb, 'Stories are the kind of writing the child has done most and he falls back on it.', 'The question "Ni sentensi ipi inafaa katika insha ya wasifu kuhusu "Mwalimu Wangu Mwadilifu"?" with "Siku moja tulienda sokoni tukapotea." among the options.', 'Ask what the reader should know about the topic at the end: what it looks like, what it is for.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU.M5_INS_DETAIL_T6', 'KISW.G5.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU', 'Describes with empty words (kizuri sana, kibaya) and no detail that makes a picture.', '{"question":"Ni sentensi ipi inajenga picha dhahiri kuhusu \"Mwalimu Wangu Mwadilifu\"?","wrong_answer":"Mwalimu wetu ni mzuri.","correct_answer":"Mwalimu Achieng ni mrefu, mpole na husikiliza kila mwanafunzi kwa makini."}'::jsonb, 'The child knows the thing well and assumes the reader sees it too.', 'The question "Ni sentensi ipi inajenga picha dhahiri kuhusu "Mwalimu Wangu Mwadilifu"?" with "Mwalimu wetu ni mzuri." among the options.', 'Five senses chart: what do you see, hear, smell, touch, taste? Turn one row into a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU.M5_INS_AGREE_T6', 'KISW.G5.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU', 'Uses a describing word that does not agree with its noun (bendera mzuri, miti mrefu).', '{"question":"Ni sentensi ipi ni sahihi?","wrong_answer":"Ana macho mikubwa ya upole.","correct_answer":"Ana macho makubwa ya upole."}'::jsonb, 'The child uses one form of the adjective (m-) for every noun, as he hears it for people.', 'The question "Ni sentensi ipi ni sahihi?" with "Ana macho mikubwa ya upole." among the options.', 'Find the noun first, then its ngeli, then the prefix of the adjective.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU.M5_INS_OFFTOPIC_T6', 'KISW.G5.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU', 'Puts in points that are not about the title.', '{"question":"Katika insha ya wasifu yenye anwani \"Mwalimu Wangu Mwadilifu\", ni sentensi ipi haifai?","wrong_answer":"Rafiki yangu ana baiskeli mpya ya rangi ya bluu.","correct_answer":"Mwalimu Achieng ni mrefu, mpole na husikiliza kila mwanafunzi kwa makini."}'::jsonb, 'The child adds whatever he remembers so the insha is long enough.', 'The question "Katika insha ya wasifu yenye anwani "Mwalimu Wangu Mwadilifu", ni sentensi ipi haifai?" with "Rafiki yangu ana baiskeli mpya ya rangi ya bluu." among the options.', 'Read each sentence and ask: does it tell the reader about the title? Cross out the ones that do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU.M5_INS_PARAS_T6', 'KISW.G5.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU', 'Writes the whole insha as one paragraph with no utangulizi, kiini and hitimisho.', '{"question":"Insha \"Mwalimu Wangu Mwadilifu\" ina sehemu zipi?","wrong_answer":"aya moja ndefu","correct_answer":"utangulizi, kiini (aya kadhaa) na hitimisho"}'::jsonb, 'The child writes until the space is full and has not planned the parts.', 'The question "Insha "Mwalimu Wangu Mwadilifu" ina sehemu zipi?" with "aya moja ndefu" among the options.', 'Fold the page into three; one part in each; one idea per paragraph in the middle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T6_NGELI_YA_U_YA.U_YA.M_UYA_AGR_ZI', 'KISW.G5.SARUFI.T6_NGELI_YA_U_YA.U_YA', 'Agrees the plural of a U-YA noun with zi- or i- instead of ya-.', '{"question":"Manyoya ___meanguka.","wrong_answer":"zi","correct_answer":"ya"}'::jsonb, 'The child uses the prefix of the better known class.', 'A plural gap with ya-, zi- and i- as options.', 'Does the plural noun begin with ma-?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T6_NGELI_YA_U_YA.U_YA.M_UYA_PL_FORM', 'KISW.G5.SARUFI.T6_NGELI_YA_U_YA.U_YA', 'Gives a wrong plural for a U-YA noun (minyoya, nyoya, unyoya).', '{"question":"Wingi wa \"unyoya\" ni ___.","wrong_answer":"minyoya","correct_answer":"manyoya"}'::jsonb, 'The child does not know that U-YA nouns take ma-.', 'Plural forms with different prefixes.', 'Say "manyoya mengi", not "minyoya".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T6_NGELI_YA_U_YA.U_YA.M_UYA_SG_WRONG', 'KISW.G5.SARUFI.T6_NGELI_YA_U_YA.U_YA', 'Agrees a singular U-YA noun with ya- or a- instead of u-.', '{"question":"Ugonjwa wake ___meisha.","wrong_answer":"ya","correct_answer":"u"}'::jsonb, 'The child sees the ya- he knows from the plural.', 'A singular gap with ya- and u- as options.', 'One illness: u- as in ugonjwa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T6_NGELI_YA_U_YA.U_YA.M5_UYA_CLASS', 'KISW.G5.SARUFI.T6_NGELI_YA_U_YA.U_YA', 'Puts a U-YA noun in U-ZI because both start with u- (ugonjwa zimeenea).', '{"question":"Jaza: Magonjwa ___ (yameenea / zimeenea).","wrong_answer":"zimeenea","correct_answer":"yameenea"}'::jsonb, 'Both classes begin with u- in the singular; the child takes the plural of the class he learnt first.', 'The question "Jaza: Magonjwa ___ (yameenea / zimeenea)." with "zimeenea" among the options.', 'Plural test: if the plural takes ma- (ugonjwa -> magonjwa), the class is U-YA and the verb takes ya-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T7_NAHAU.NAHAU.M_NAH_LITERAL', 'KISW.G5.KUSIKI.T7_NAHAU.NAHAU', 'Reads the nahau word for word.', '{"question":"\"Kukata tamaa\" maana yake ni nini?","wrong_answer":"kukata kamba ya tamaa","correct_answer":"kuacha kuwa na matumaini"}'::jsonb, 'The child does not know that a nahau has its own meaning.', 'A meaning question with a literal option.', 'Ask whether anyone really cuts tamaa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T7_NAHAU.NAHAU.M_NAH_WRONG_MEANING', 'KISW.G5.KUSIKI.T7_NAHAU.NAHAU', 'Gives the meaning of another nahau.', '{"question":"\"Kula chumvi\" maana yake ni nini?","wrong_answer":"kuwa na hamu ya kula","correct_answer":"kuwa na umri mkubwa na uzoefu"}'::jsonb, 'The child knows several nahau but swaps meanings.', 'The meaning of another nahau as an option.', 'Ask what experience chumvi stands for.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T7_NAHAU.NAHAU.M_NAH_WRONG_WORD', 'KISW.G5.KUSIKI.T7_NAHAU.NAHAU', 'Completes the nahau with a different word (kukata moyo for kukata tamaa).', '{"question":"Usikate ___ ukishindwa mara moja.","wrong_answer":"kamba","correct_answer":"tamaa"}'::jsonb, 'The child remembers the shape but changes a word.', 'A nahau gap where a near word is an option.', 'Recite the whole nahau.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T7_NAHAU.NAHAU.M5_NAH_USE', 'KISW.G5.KUSIKI.T7_NAHAU.NAHAU', 'Uses the nahau in a sentence where its meaning does not fit (Alipiga deki mto).', '{"question":"Ni sentensi ipi imetumia \"kupiga deki\" ipasavyo?","wrong_answer":"Mvuvi alipiga deki mto.","correct_answer":"Mama alipiga deki sakafu ya nyumba."}'::jsonb, 'The child knows the words of the nahau but not the situation it belongs to.', 'The question "Ni sentensi ipi imetumia "kupiga deki" ipasavyo?" with "Mvuvi alipiga deki mto." among the options.', 'Ask what the nahau means, then whether the sentence describes that.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M5_MAP_COVER_T7', 'KISW.G5.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Chooses a book by its cover picture or its thickness only.', '{"question":"Unataka kusoma kuhusu elimu ya mazingira. Utachaguaje kitabu?","wrong_answer":"kwa picha nzuri ya jalada","correct_answer":"kwa kusoma anwani, maelezo ya nyuma na ukurasa wa kwanza"}'::jsonb, 'Nobody has shown the child the title, the blurb and the first page as clues.', 'The question "Unataka kusoma kuhusu elimu ya mazingira. Utachaguaje kitabu?" with "kwa picha nzuri ya jalada" among the options.', 'Hold up two books; read the title and the back of each aloud; the child chooses and says which clue decided it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M5_MAP_LEVEL_T7', 'KISW.G5.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Chooses a text far above his reading level and gives up after a page.', '{"question":"Ukisoma ukurasa wa kwanza wa \"Mto Wetu Unalia\" na hujui maneno mengi sana, ufanye nini?","wrong_answer":"endelea tu hata kama huelewi","correct_answer":"chagua matini nyingine iliyo ya kiwango chako"}'::jsonb, 'The child thinks a harder book is a better book, or chooses the book a friend chose.', 'The question "Ukisoma ukurasa wa kwanza wa "Mto Wetu Unalia" na hujui maneno mengi sana, ufanye nini?" with "endelea tu hata kama huelewi" among the options.', 'The five-finger check: on one page, a finger for each unknown word; five fingers means the book is too hard for now.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M5_MAP_TITLEMSG_T7', 'KISW.G5.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Gives the title as the message of the text.', '{"question":"Ujumbe wa matini \"Mto Wetu Unalia\" ni upi?","wrong_answer":"Mto Wetu Unalia","correct_answer":"Tukitunza mazingira, mazingira yatatutunza."}'::jsonb, 'The title is the only sentence about the whole text that the child is sure of.', 'The question "Ujumbe wa matini "Mto Wetu Unalia" ni upi?" with "Mto Wetu Unalia" among the options.', 'Ask what the writer wants the reader to learn or do; the title only names the topic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M5_MAP_DETAIL_T7', 'KISW.G5.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Gives one detail of the text as its message.', '{"question":"Ni ipi ni ujumbe wa matini kuhusu elimu ya mazingira?","wrong_answer":"Watoto waliokota chupa za plastiki kando ya mto.","correct_answer":"Tukitunza mazingira, mazingira yatatutunza."}'::jsonb, 'The detail was striking and is remembered; the child has not asked what the whole text is about.', 'The question "Ni ipi ni ujumbe wa matini kuhusu elimu ya mazingira?" with "Watoto waliokota chupa za plastiki kando ya mto." among the options.', 'Two boxes: "ujumbe" (one) and "maelezo" (many); the child sorts sentences from the text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M5_MAP_KIND_T7', 'KISW.G5.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Does not tell one kind of text from another (takes a newspaper report for a story, or a poem for a story).', '{"question":"Matini yenye beti na mishororo ni ya aina gani?","wrong_answer":"hadithi","correct_answer":"shairi"}'::jsonb, 'The child has met most texts as "kitabu" and has not been shown the signs of each kind.', 'The question "Matini yenye beti na mishororo ni ya aina gani?" with "hadithi" among the options.', 'Lay out a story, a poem, a newspaper page and a dictionary; the child names one sign of each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M5_MAP_WORD_T7', 'KISW.G5.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Guesses a new word from how it looks, not from the sentence it is in (taka).', '{"question":"Katika matini: \"Watu walitupa taka mtoni na maji yakachafuka.\" Neno \"taka\" lina maana gani?","wrong_answer":"kutaka kitu","correct_answer":"vitu visivyotakiwa vinavyotupwa"}'::jsonb, 'The child matches the word to a word it looks like instead of reading the sentence around it.', 'The question "Katika matini: "Watu walitupa taka mtoni na maji yakachafuka." Neno "taka" lina maana gani?" with "kutaka kitu" among the options.', 'Cover the word; the child reads the sentence and says what word would fit; then compares.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T7_INSHA_YA_MAELEZO.INSHA_MAELEZO.M5_INS_STORY_T7', 'KISW.G5.KUANDI.T7_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Tells a story of what happened where the insha should explain or describe.', '{"question":"Ni sentensi ipi inafaa katika insha ya maelezo kuhusu \"Jinsi ya Kutunza Mazingira ya Shule\"?","wrong_answer":"Siku moja tulienda sokoni tukapotea.","correct_answer":"Kila Ijumaa, tunaokota taka na kuzitupa kwenye pipa la taka."}'::jsonb, 'Stories are the kind of writing the child has done most and he falls back on it.', 'The question "Ni sentensi ipi inafaa katika insha ya maelezo kuhusu "Jinsi ya Kutunza Mazingira ya Shule"?" with "Siku moja tulienda sokoni tukapotea." among the options.', 'Ask what the reader should know about the topic at the end: what it is, how it works or is done.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T7_INSHA_YA_MAELEZO.INSHA_MAELEZO.M5_INS_DETAIL_T7', 'KISW.G5.KUANDI.T7_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Describes with empty words (kizuri sana, kibaya) and no detail that makes a picture.', '{"question":"Ni sentensi ipi inajenga picha dhahiri kuhusu \"Jinsi ya Kutunza Mazingira ya Shule\"?","wrong_answer":"Mazingira ni muhimu.","correct_answer":"Kila Ijumaa, tunaokota taka na kuzitupa kwenye pipa la taka."}'::jsonb, 'The child knows the thing well and assumes the reader sees it too.', 'The question "Ni sentensi ipi inajenga picha dhahiri kuhusu "Jinsi ya Kutunza Mazingira ya Shule"?" with "Mazingira ni muhimu." among the options.', 'Five senses chart: what do you see, hear, smell, touch, taste? Turn one row into a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T7_INSHA_YA_MAELEZO.INSHA_MAELEZO.M5_INS_STEPS_T7', 'KISW.G5.KUANDI.T7_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Gives the steps of how to do something in a mixed-up order.', '{"question":"Ni mpangilio upi unafaa katika maelezo ya \"Jinsi ya Kutunza Mazingira ya Shule\"?","wrong_answer":"panda maua, tupa kwenye pipa, tenganisha taka, okota taka","correct_answer":"okota taka, tenganisha taka, tupa kwenye pipa, panda maua"}'::jsonb, 'The child remembers the steps as a set, not as a sequence.', 'The question "Ni mpangilio upi unafaa katika maelezo ya "Jinsi ya Kutunza Mazingira ya Shule"?" with "panda maua, tupa kwenye pipa, tenganisha taka, okota taka" among the options.', 'Act out the steps; number them; write them with kwanza, kisha, mwishowe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T7_INSHA_YA_MAELEZO.INSHA_MAELEZO.M5_INS_OFFTOPIC_T7', 'KISW.G5.KUANDI.T7_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Puts in points that are not about the title.', '{"question":"Katika insha ya maelezo yenye anwani \"Jinsi ya Kutunza Mazingira ya Shule\", ni sentensi ipi haifai?","wrong_answer":"Rafiki yangu ana baiskeli mpya ya rangi ya bluu.","correct_answer":"Kila Ijumaa, tunaokota taka na kuzitupa kwenye pipa la taka."}'::jsonb, 'The child adds whatever he remembers so the insha is long enough.', 'The question "Katika insha ya maelezo yenye anwani "Jinsi ya Kutunza Mazingira ya Shule", ni sentensi ipi haifai?" with "Rafiki yangu ana baiskeli mpya ya rangi ya bluu." among the options.', 'Read each sentence and ask: does it tell the reader about the title? Cross out the ones that do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T7_INSHA_YA_MAELEZO.INSHA_MAELEZO.M5_INS_PARAS_T7', 'KISW.G5.KUANDI.T7_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Writes the whole insha as one paragraph with no utangulizi, kiini and hitimisho.', '{"question":"Insha \"Jinsi ya Kutunza Mazingira ya Shule\" ina sehemu zipi?","wrong_answer":"aya moja ndefu","correct_answer":"utangulizi, kiini (aya kadhaa) na hitimisho"}'::jsonb, 'The child writes until the space is full and has not planned the parts.', 'The question "Insha "Jinsi ya Kutunza Mazingira ya Shule" ina sehemu zipi?" with "aya moja ndefu" among the options.', 'Fold the page into three; one part in each; one idea per paragraph in the middle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T7_NGELI_YA_KU_KU.KU_KU.M_KUKU_AGR_A', 'KISW.G5.SARUFI.T7_NGELI_YA_KU_KU.KU_KU', 'Agrees a verbal noun with a- (a person) instead of ku-.', '{"question":"Kusoma ___napendeza.","wrong_answer":"a","correct_answer":"ku"}'::jsonb, 'The child thinks of the person who reads, not of the action.', 'A gap with a-, u-, i- and ku- as options.', 'The first word is kusoma, which begins with ku-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T7_NGELI_YA_KU_KU.KU_KU.M_KUKU_AGR_U', 'KISW.G5.SARUFI.T7_NGELI_YA_KU_KU.KU_KU', 'Agrees a verbal noun with u- or i- as with U-I.', '{"question":"Kucheza ___nafurahisha.","wrong_answer":"u","correct_answer":"ku"}'::jsonb, 'The child pairs ku- nouns with prefixes of the classes he knows best.', 'A gap with u-, i- and ku- as options.', 'Say the sentence with the prefix that is the same as the noun starts with.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T7_NGELI_YA_KU_KU.KU_KU.M_KUKU_PLURAL', 'KISW.G5.SARUFI.T7_NGELI_YA_KU_KU.KU_KU', 'Gives a plural (makusoma, vikusoma) to a verbal noun.', '{"question":"Wingi wa \"kusoma\" ni ___.","wrong_answer":"makusoma","correct_answer":"kusoma"}'::jsonb, 'The child thinks every noun has a plural.', 'A plural question where the right answer is that nothing changes.', 'Ask whether you can say "makusoma".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T7_NGELI_YA_KU_KU.KU_KU.M5_KUKU_POSS', 'KISW.G5.SARUFI.T7_NGELI_YA_KU_KU.KU_KU', 'Uses the possessive or adjective of another class with a verbal noun (kuimba yake, kusoma kizuri).', '{"question":"Jaza: Kuimba ___ kulifurahisha watu (kwake / yake).","wrong_answer":"yake","correct_answer":"kwake"}'::jsonb, 'The child agrees the possessive with the person who sings, not with the verbal noun.', 'The question "Jaza: Kuimba ___ kulifurahisha watu (kwake / yake)." with "yake" among the options.', 'Everything that agrees with a verbal noun takes kw-/ku-: kuimba kwake, kusoma kuzuri.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T8_VISAWE.VISAWE.M_VIS_OPPOSITE', 'KISW.G5.KUSIKI.T8_VISAWE.VISAWE', 'Picks the opposite where the same meaning is asked.', '{"question":"Kisawe cha \"furaha\" ni ___.","wrong_answer":"huzuni","correct_answer":"bashasha"}'::jsonb, 'The child links furaha and huzuni because they go together.', 'A synonym question with the opposite as an option.', 'Ask whether the two words mean the same.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T8_VISAWE.VISAWE.M_VIS_RELATED', 'KISW.G5.KUSIKI.T8_VISAWE.VISAWE', 'Picks a word about the same topic but with a different meaning.', '{"question":"Kisawe cha \"huzuni\" ni ___.","wrong_answer":"kilio","correct_answer":"simanzi"}'::jsonb, 'The child picks what goes with the word, not what means the same.', 'A related word as an option.', 'Could you swap the two words in a sentence and keep the same meaning?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T8_VISAWE.VISAWE.M_VIS_LOOKALIKE', 'KISW.G5.KUSIKI.T8_VISAWE.VISAWE', 'Picks a word that looks or sounds like the word.', '{"question":"Kisawe cha \"haraka\" ni ___.","wrong_answer":"harufu","correct_answer":"upesi"}'::jsonb, 'The child goes by the first letters.', 'A look-alike word as an option.', 'Say what each word means.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T8_VISAWE.VISAWE.M5_VIS_THREE', 'KISW.G5.KUSIKI.T8_VISAWE.VISAWE', 'Finds two synonyms but adds a third word that is only related (pesa, fedha, mfuko).', '{"question":"Ni maneno yapi matatu yenye maana sawa?","wrong_answer":"pesa, fedha, mfuko","correct_answer":"pesa, fedha, hela"}'::jsonb, 'The related word (a purse holds money) belongs to the same picture, and the child counts it.', 'The question "Ni maneno yapi matatu yenye maana sawa?" with "pesa, fedha, mfuko" among the options.', 'Put each word into the same sentence; the one that changes the meaning is out.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO.M_IGI_STAGE_AS_SPEECH', 'KISW.G5.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO', 'Reads the words in brackets (what to do on stage) as words a character says.', '{"question":"Maelekezo ya jukwaani katika igizo ni yapi?","wrong_answer":"Mama: Nenda sokoni.","correct_answer":"(Anafungua mlango)"}'::jsonb, 'The child reads a play as a story.', 'A play with brackets and spoken lines.', 'Brackets tell the actor what to do, not what to say.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO.M_IGI_STORY', 'KISW.G5.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO', 'Does not tell a play from a story.', '{"question":"Ni kipi kati ya hivi ni igizo?","wrong_answer":"Wanjiru alienda sokoni.","correct_answer":"Wanjiru: Naenda sokoni."}'::jsonb, 'The child sees a short text and does not look at the form.', 'A play and a story on the same event.', 'Look for the speaker names with a colon.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO.M_IGI_WRONG_SPEAKER', 'KISW.G5.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO', 'Gives a character who did not say the line.', '{"question":"Nani alisema \"Nitakuletea maji\"?","wrong_answer":"Baba","correct_answer":"Mwajuma"}'::jsonb, 'The child does not follow the names before the colons.', 'A who-said-it question.', 'Find the line and read the name before it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO.M_IGI_DETAIL', 'KISW.G5.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO', 'Gives a wrong detail of the play (the place, the thing bought).', '{"question":"Akinyi alienda wapi?","wrong_answer":"jikoni","correct_answer":"sokoni"}'::jsonb, 'The child remembers a place named near the question.', 'A where-or-what question with another detail of the play.', 'Find the line where it is said.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO.M_IGI_VOCAB', 'KISW.G5.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO', 'Gives the wrong meaning of a word in the play.', '{"question":"Neno \"kuandamana\" lina maana gani katika igizo?","wrong_answer":"kukimbia peke yake","correct_answer":"kwenda pamoja na mtu"}'::jsonb, 'The child guesses from the look of the word.', 'A meaning question for a word in the play.', 'Read the line where the word is used and think who goes with whom.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T8_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI.M5_INS_FACTS_T8', 'KISW.G5.KUANDI.T8_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI', 'Writes facts or an explanation where a story of events is asked.', '{"question":"Ni sentensi ipi ni mwanzo wa insha ya masimulizi yenye anwani \"Ndege Aliyenaswa\"?","wrong_answer":"Tai ni ndege mkubwa anayekula wanyama wadogo.","correct_answer":"Tulimwona tai amenaswa kwenye wavu wa mkulima."}'::jsonb, 'The child knows a lot about the topic and writes what he knows instead of telling what happened.', 'The question "Ni sentensi ipi ni mwanzo wa insha ya masimulizi yenye anwani "Ndege Aliyenaswa"?" with "Tai ni ndege mkubwa anayekula wanyama wadogo." among the options.', 'Ask: who, where, what happened first, then, in the end? A story answers these; an explanation does not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T8_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI.M5_INS_TENSE_T8', 'KISW.G5.KUANDI.T8_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI', 'Tells a past story in the present tense (-na-), or mixes -na- and -li- in one story.', '{"question":"Ni sentensi ipi inafaa katika masimulizi ya jambo lililotokea jana: \"Ndege Aliyenaswa\"?","wrong_answer":"Tunamwona tai amenaswa kwenye wavu wa mkulima.","correct_answer":"Tulimwona tai amenaswa kwenye wavu wa mkulima."}'::jsonb, 'The child writes as he speaks while remembering, and English stories in class are told in the present too.', 'The question "Ni sentensi ipi inafaa katika masimulizi ya jambo lililotokea jana: "Ndege Aliyenaswa"?" with "Tunamwona tai amenaswa kwenye wavu wa mkulima." among the options.', 'Circle every verb; check its tense marker against the time words (jana, siku moja).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T8_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI.M5_INS_ORDER_T8', 'KISW.G5.KUANDI.T8_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI', 'Puts the events in an order that cannot have happened (the end before the start), with no linking words.', '{"question":"Ni mpangilio upi wa matukio unafaa katika insha \"Ndege Aliyenaswa\"?","wrong_answer":"tai aliruka, tulikata wavu, tulimwita mlinzi, tulimwona tai","correct_answer":"tulimwona tai, tulimwita mlinzi, tulikata wavu, tai aliruka"}'::jsonb, 'The child writes events as they come to mind; nobody has asked for a plan first.', 'The question "Ni mpangilio upi wa matukio unafaa katika insha "Ndege Aliyenaswa"?" with "tai aliruka, tulikata wavu, tulimwita mlinzi, tulimwona tai" among the options.', 'Plan with three boxes (mwanzo, kati, mwisho) and linking words (kwanza, kisha, hatimaye) before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T8_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI.M5_INS_END_T8', 'KISW.G5.KUANDI.T8_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI', 'Ends the insha abruptly ("Mwisho." or "The end") with no closing paragraph (hitimisho).', '{"question":"Ni ipi ni hitimisho bora la insha \"Ndege Aliyenaswa\"?","wrong_answer":"Mwisho.","correct_answer":"Tangu siku hiyo, nimejifunza kuwa mwangalifu kila wakati."}'::jsonb, 'Storybooks for young readers end with "Mwisho" and the child copies that.', 'The question "Ni ipi ni hitimisho bora la insha "Ndege Aliyenaswa"?" with "Mwisho." among the options.', 'Show three endings; the child picks the one that closes the main idea or the lesson.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T8_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI.M5_INS_TITLE_T8', 'KISW.G5.KUANDI.T8_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI', 'Writes the title as a full sentence with a full stop, or leaves it out.', '{"question":"Ni anwani ipi imeandikwa ipasavyo?","wrong_answer":"ndege aliyenaswa.","correct_answer":"NDEGE ALIYENASWA"}'::jsonb, 'The child treats the title as the first sentence of the insha.', 'The question "Ni anwani ipi imeandikwa ipasavyo?" with "ndege aliyenaswa." among the options.', 'Show where the title sits and how it is written (herufi kubwa, no kikomo, often underlined).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T8_MNYAMBULIKO_WA_VITEN.MNYAMBULIKO.M_MNY_MIX_FORMS', 'KISW.G5.SARUFI.T8_MNYAMBULIKO_WA_VITEN.MNYAMBULIKO', 'Mixes kutendeka (can be done, becomes done) with kutendewa (done for someone).', '{"question":"Kikombe kilianguka na ___.","wrong_answer":"kilivunjiwa","correct_answer":"kilivunjika"}'::jsonb, 'The endings -ika and -ewa both change the verb and look alike.', 'Verb forms that differ in meaning: done for someone, can be done.', 'Ask: is someone helped, or can the thing simply be done?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T8_MNYAMBULIKO_WA_VITEN.MNYAMBULIKO.M_MNY_TENDANA_ONE', 'KISW.G5.SARUFI.T8_MNYAMBULIKO_WA_VITEN.MNYAMBULIKO', 'Leaves the verb in its base form where each does it to the other (wanasalimu for wanasalimiana).', '{"question":"Marafiki wawili ___ kila asubuhi.","wrong_answer":"wanasalimu","correct_answer":"wanasalimiana"}'::jsonb, 'The child keeps the base verb and does not show that each does it to the other.', 'A gap that needs "to each other".', 'Ask whether they do it to each other.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T8_MNYAMBULIKO_WA_VITEN.MNYAMBULIKO.M_MNY_NO_CHANGE', 'KISW.G5.SARUFI.T8_MNYAMBULIKO_WA_VITEN.MNYAMBULIKO', 'Leaves the verb unchanged (soma) where an ending is needed (somewa, someka).', '{"question":"Mama alimpikia mtoto uji. Mtoto ___ uji na mama.","wrong_answer":"alipika","correct_answer":"alipikiwa"}'::jsonb, 'The child does not hear the change in meaning an ending brings.', 'A gap that needs a changed verb.', 'Ask whom the action is done for or by.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T8_MNYAMBULIKO_WA_VITEN.MNYAMBULIKO.M5_MNY_TENDEKA_E', 'KISW.G5.SARUFI.T8_MNYAMBULIKO_WA_VITEN.MNYAMBULIKO', 'Forms kutendeka with -ika where -eka is needed, or the reverse (someka/somika, chezeka/chezika).', '{"question":"Kauli ya kutendeka ya \"soma\" ni ipi?","wrong_answer":"somika","correct_answer":"someka"}'::jsonb, 'The vowel of the ending follows the vowel of the stem (e/o take -eka; a/i/u take -ika), which the child has not been shown.', 'The question "Kauli ya kutendeka ya "soma" ni ipi?" with "somika" among the options.', 'Sort stems by their last vowel: soma, cheza, ona -> -eka; pika, funga, kata -> -ika.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.LUGHA_RASMI.M5_RAS_SETTING', 'KISW.G5.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.LUGHA_RASMI', 'Takes an informal setting (playing at home, a chat with a cousin) for an official one, or the reverse.', '{"question":"Ni muktadha upi ni rasmi?","wrong_answer":"kuzungumza na binamu nyumbani","correct_answer":"kumweleza daktari dalili za ugonjwa kliniki"}'::jsonb, 'The child judges by who is there (a grown-up) and not by the purpose and place.', 'The question "Ni muktadha upi ni rasmi?" with "kuzungumza na binamu nyumbani" among the options.', 'Sort setting cards by place and purpose: is there an office, a duty, a record?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.LUGHA_RASMI.M5_RAS_SHENG', 'KISW.G5.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.LUGHA_RASMI', 'Uses Sheng or slang to an official (Daktari, niko poa tu, ni homa kiasi).', '{"question":"Daktari anakuuliza unajisikiaje. Unajibu vipi?","wrong_answer":"Niko poa tu daktari, ni ka-homa.","correct_answer":"Ninaumwa na kichwa na nina homa tangu jana, daktari."}'::jsonb, 'The child speaks to everyone in the language of friends.', 'The question "Daktari anakuuliza unajisikiaje. Unajibu vipi?" with "Niko poa tu daktari, ni ka-homa." among the options.', 'Record one answer in Sheng and one in standard Kiswahili; which helps the doctor more?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.LUGHA_RASMI.M5_RAS_TITLE', 'KISW.G5.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.LUGHA_RASMI', 'Addresses an official by first name or with no title (Hello Wanjiku! to the head teacher).', '{"question":"Unaingia ofisini kwa Mwalimu Mkuu. Unasema?","wrong_answer":"Habari Wanjiku!","correct_answer":"Shikamoo Mwalimu Mkuu. Naomba kuingia."}'::jsonb, 'At home and with friends names are used; the child has not been taught titles.', 'The question "Unaingia ofisini kwa Mwalimu Mkuu. Unasema?" with "Habari Wanjiku!" among the options.', 'List titles: Mwalimu Mkuu, Daktari, Chifu, Mheshimiwa; use them in every role play.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.LUGHA_RASMI.M5_RAS_INTERRUPT', 'KISW.G5.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.LUGHA_RASMI', 'Interrupts an official or speaks out of turn in a meeting.', '{"question":"Katika mkutano wa shule, unataka kuuliza swali. Ufanye nini?","wrong_answer":"uliza mara moja hata kama mwenzako anazungumza","correct_answer":"inua mkono na usubiri kupewa nafasi"}'::jsonb, 'Turn-taking rules of class are not linked to other official settings.', 'The question "Katika mkutano wa shule, unataka kuuliza swali. Ufanye nini?" with "uliza mara moja hata kama mwenzako anazungumza" among the options.', 'Run a mock meeting with a chair; only the person given the floor speaks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M5_MAP_COVER_T9', 'KISW.G5.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Chooses a book by its cover picture or its thickness only.', '{"question":"Unataka kusoma kuhusu magonjwa. Utachaguaje kitabu?","wrong_answer":"kwa picha nzuri ya jalada","correct_answer":"kwa kusoma anwani, maelezo ya nyuma na ukurasa wa kwanza"}'::jsonb, 'Nobody has shown the child the title, the blurb and the first page as clues.', 'The question "Unataka kusoma kuhusu magonjwa. Utachaguaje kitabu?" with "kwa picha nzuri ya jalada" among the options.', 'Hold up two books; read the title and the back of each aloud; the child chooses and says which clue decided it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M5_MAP_LEVEL_T9', 'KISW.G5.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Chooses a text far above his reading level and gives up after a page.', '{"question":"Ukisoma ukurasa wa kwanza wa \"Malaria Haina Nafasi Kwetu\" na hujui maneno mengi sana, ufanye nini?","wrong_answer":"endelea tu hata kama huelewi","correct_answer":"chagua matini nyingine iliyo ya kiwango chako"}'::jsonb, 'The child thinks a harder book is a better book, or chooses the book a friend chose.', 'The question "Ukisoma ukurasa wa kwanza wa "Malaria Haina Nafasi Kwetu" na hujui maneno mengi sana, ufanye nini?" with "endelea tu hata kama huelewi" among the options.', 'The five-finger check: on one page, a finger for each unknown word; five fingers means the book is too hard for now.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M5_MAP_TITLEMSG_T9', 'KISW.G5.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Gives the title as the message of the text.', '{"question":"Ujumbe wa matini \"Malaria Haina Nafasi Kwetu\" ni upi?","wrong_answer":"Malaria Haina Nafasi Kwetu","correct_answer":"Tukilala ndani ya chandarua na kufukia madimbwi, tunajikinga na malaria."}'::jsonb, 'The title is the only sentence about the whole text that the child is sure of.', 'The question "Ujumbe wa matini "Malaria Haina Nafasi Kwetu" ni upi?" with "Malaria Haina Nafasi Kwetu" among the options.', 'Ask what the writer wants the reader to learn or do; the title only names the topic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M5_MAP_DETAIL_T9', 'KISW.G5.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Gives one detail of the text as its message.', '{"question":"Ni ipi ni ujumbe wa matini kuhusu magonjwa?","wrong_answer":"Mama alinunua chandarua kipya sokoni.","correct_answer":"Tukilala ndani ya chandarua na kufukia madimbwi, tunajikinga na malaria."}'::jsonb, 'The detail was striking and is remembered; the child has not asked what the whole text is about.', 'The question "Ni ipi ni ujumbe wa matini kuhusu magonjwa?" with "Mama alinunua chandarua kipya sokoni." among the options.', 'Two boxes: "ujumbe" (one) and "maelezo" (many); the child sorts sentences from the text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M5_MAP_KIND_T9', 'KISW.G5.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Does not tell one kind of text from another (takes a newspaper report for a story, or a poem for a story).', '{"question":"Matini yenye beti na mishororo ni ya aina gani?","wrong_answer":"hadithi","correct_answer":"shairi"}'::jsonb, 'The child has met most texts as "kitabu" and has not been shown the signs of each kind.', 'The question "Matini yenye beti na mishororo ni ya aina gani?" with "hadithi" among the options.', 'Lay out a story, a poem, a newspaper page and a dictionary; the child names one sign of each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M5_MAP_WORD_T9', 'KISW.G5.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Guesses a new word from how it looks, not from the sentence it is in (dalili).', '{"question":"Katika matini: \"Homa na kutetemeka ni dalili za malaria.\" Neno \"dalili\" lina maana gani?","wrong_answer":"dawa ya ugonjwa","correct_answer":"ishara zinazoonyesha ugonjwa"}'::jsonb, 'The child matches the word to a word it looks like instead of reading the sentence around it.', 'The question "Katika matini: "Homa na kutetemeka ni dalili za malaria." Neno "dalili" lina maana gani?" with "dawa ya ugonjwa" among the options.', 'Cover the word; the child reads the sentence and says what word would fit; then compares.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T9_INSHA_YA_MAELEZO.INSHA_MAELEZO.M5_INS_STORY_T9', 'KISW.G5.KUANDI.T9_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Tells a story of what happened where the insha should explain or describe.', '{"question":"Ni sentensi ipi inafaa katika insha ya maelezo kuhusu \"Jinsi ya Kujikinga na Malaria\"?","wrong_answer":"Siku moja tulienda sokoni tukapotea.","correct_answer":"Kwanza, lala ndani ya chandarua kilichotiwa dawa kila usiku."}'::jsonb, 'Stories are the kind of writing the child has done most and he falls back on it.', 'The question "Ni sentensi ipi inafaa katika insha ya maelezo kuhusu "Jinsi ya Kujikinga na Malaria"?" with "Siku moja tulienda sokoni tukapotea." among the options.', 'Ask what the reader should know about the topic at the end: what it is, how it works or is done.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T9_INSHA_YA_MAELEZO.INSHA_MAELEZO.M5_INS_DETAIL_T9', 'KISW.G5.KUANDI.T9_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Describes with empty words (kizuri sana, kibaya) and no detail that makes a picture.', '{"question":"Ni sentensi ipi inajenga picha dhahiri kuhusu \"Jinsi ya Kujikinga na Malaria\"?","wrong_answer":"Malaria ni ugonjwa mbaya.","correct_answer":"Kwanza, lala ndani ya chandarua kilichotiwa dawa kila usiku."}'::jsonb, 'The child knows the thing well and assumes the reader sees it too.', 'The question "Ni sentensi ipi inajenga picha dhahiri kuhusu "Jinsi ya Kujikinga na Malaria"?" with "Malaria ni ugonjwa mbaya." among the options.', 'Five senses chart: what do you see, hear, smell, touch, taste? Turn one row into a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T9_INSHA_YA_MAELEZO.INSHA_MAELEZO.M5_INS_STEPS_T9', 'KISW.G5.KUANDI.T9_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Gives the steps of how to do something in a mixed-up order.', '{"question":"Ni mpangilio upi unafaa katika maelezo ya \"Jinsi ya Kujikinga na Malaria\"?","wrong_answer":"nenda kliniki ukiugua, lala ndani ya chandarua, fukia madimbwi, fyeka nyasi","correct_answer":"fyeka nyasi, fukia madimbwi, lala ndani ya chandarua, nenda kliniki ukiugua"}'::jsonb, 'The child remembers the steps as a set, not as a sequence.', 'The question "Ni mpangilio upi unafaa katika maelezo ya "Jinsi ya Kujikinga na Malaria"?" with "nenda kliniki ukiugua, lala ndani ya chandarua, fukia madimbwi, fyeka nyasi" among the options.', 'Act out the steps; number them; write them with kwanza, kisha, mwishowe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T9_INSHA_YA_MAELEZO.INSHA_MAELEZO.M5_INS_OFFTOPIC_T9', 'KISW.G5.KUANDI.T9_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Puts in points that are not about the title.', '{"question":"Katika insha ya maelezo yenye anwani \"Jinsi ya Kujikinga na Malaria\", ni sentensi ipi haifai?","wrong_answer":"Rafiki yangu ana baiskeli mpya ya rangi ya bluu.","correct_answer":"Kwanza, lala ndani ya chandarua kilichotiwa dawa kila usiku."}'::jsonb, 'The child adds whatever he remembers so the insha is long enough.', 'The question "Katika insha ya maelezo yenye anwani "Jinsi ya Kujikinga na Malaria", ni sentensi ipi haifai?" with "Rafiki yangu ana baiskeli mpya ya rangi ya bluu." among the options.', 'Read each sentence and ask: does it tell the reader about the title? Cross out the ones that do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T9_INSHA_YA_MAELEZO.INSHA_MAELEZO.M5_INS_PARAS_T9', 'KISW.G5.KUANDI.T9_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Writes the whole insha as one paragraph with no utangulizi, kiini and hitimisho.', '{"question":"Insha \"Jinsi ya Kujikinga na Malaria\" ina sehemu zipi?","wrong_answer":"aya moja ndefu","correct_answer":"utangulizi, kiini (aya kadhaa) na hitimisho"}'::jsonb, 'The child writes until the space is full and has not planned the parts.', 'The question "Insha "Jinsi ya Kujikinga na Malaria" ina sehemu zipi?" with "aya moja ndefu" among the options.', 'Fold the page into three; one part in each; one idea per paragraph in the middle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T9_VINYUME_VYA_VITENZI.VINYUME.M_VIN_NEGATE', 'KISW.G5.SARUFI.T9_VINYUME_VYA_VITENZI.VINYUME', 'Makes the opposite of a verb by adding si or ha (sifunga) instead of the opposite verb.', '{"question":"Kinyume cha \"kufunga\" ni ___.","wrong_answer":"kutofunga","correct_answer":"kufungua"}'::jsonb, 'The child takes "not doing it" to be the opposite.', 'An opposite question with a negative form as one option.', 'Is there one word that means the reverse action?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T9_VINYUME_VYA_VITENZI.VINYUME.M_VIN_WRONG_SUFFIX', 'KISW.G5.SARUFI.T9_VINYUME_VYA_VITENZI.VINYUME', 'Forms the opposite by adding -ua or -ulia to every verb (kuvaa to kuvaua).', '{"question":"Kinyume cha \"kuvaa\" ni ___.","wrong_answer":"kuvaua","correct_answer":"kuvua"}'::jsonb, 'The child copies kufunga - kufungua for every verb.', 'An opposite where the pattern -ua does not work.', 'Say the word aloud: does it exist?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T9_VINYUME_VYA_VITENZI.VINYUME.M_VIN_SYNONYM', 'KISW.G5.SARUFI.T9_VINYUME_VYA_VITENZI.VINYUME', 'Gives a word of similar meaning instead of the opposite.', '{"question":"Kinyume cha \"kuingia\" ni ___.","wrong_answer":"kuingilia","correct_answer":"kutoka"}'::jsonb, 'The child keeps the same idea and does not reverse it.', 'An opposite question with a synonym as one option.', 'Does the word mean the same, or the other way round?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T9_VINYUME_VYA_VITENZI.VINYUME.M5_VIN_UA_STEM', 'KISW.G5.SARUFI.T9_VINYUME_VYA_VITENZI.VINYUME', 'Reverses a verb with -ua where the opposite is a different word (kuja -> kujua for kwenda; kupanda -> kupandua for kushuka).', '{"question":"Kinyume cha \"panda (mlima)\" ni?","wrong_answer":"pandua","correct_answer":"shuka"}'::jsonb, 'Funga/fungua and vaa/vua teach -ua as the rule for every verb.', 'The question "Kinyume cha "panda (mlima)" ni?" with "pandua" among the options.', 'Sort verbs: those reversed with -ua (funga/fungua, vaa/vua) and those with another word (panda/shuka, ingia/toka).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T10_TASHBIHI.TASHBIHI.M_TASH_WRONG_ANIMAL', 'KISW.G5.KUSIKI.T10_TASHBIHI.TASHBIHI', 'Gives the wrong animal or thing in the simile (mkali kama sungura).', '{"question":"Baba yetu ni mkali kama ___.","wrong_answer":"sungura","correct_answer":"simba"}'::jsonb, 'The child knows the idea but not the usual comparison.', 'A simile with plausible animals as options.', 'Which animal do we say is fierce?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T10_TASHBIHI.TASHBIHI.M_TASH_NO_KAMA', 'KISW.G5.KUSIKI.T10_TASHBIHI.TASHBIHI', 'Leaves out kama or "mithili ya", and says "Yeye ni simba" as a simile.', '{"question":"Ni tashbihi ipi?","wrong_answer":"Yeye ni simba","correct_answer":"Yeye ni mkali kama simba"}'::jsonb, 'The child mixes a simile with a metaphor.', 'A simile and a metaphor as options.', 'A simile has the word kama or mithili ya.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T10_TASHBIHI.TASHBIHI.M_TASH_LITERAL', 'KISW.G5.KUSIKI.T10_TASHBIHI.TASHBIHI', 'Takes the simile word for word (the person is really a lion).', '{"question":"\"Juma ni mwoga kama sungura\" maana yake nini?","wrong_answer":"Juma ni sungura","correct_answer":"Juma ana hofu nyingi"}'::jsonb, 'The child does not read the comparison as a way to describe behaviour.', 'A meaning question for a simile.', 'Ask what behaviour the animal stands for.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T10_TASHBIHI.TASHBIHI.M5_TASH_OPPOSITE', 'KISW.G5.KUSIKI.T10_TASHBIHI.TASHBIHI', 'Uses a simile for the opposite character (mwaminifu kama fisi).', '{"question":"Kamilisha: mjanja kama ___","wrong_answer":"kondoo","correct_answer":"sungura"}'::jsonb, 'The child knows the animals of the folk tales but mixes which stands for what.', 'The question "Kamilisha: mjanja kama ___" with "kondoo" among the options.', 'Recall the folk tales: Sungura is clever, Fisi is greedy, Kondoo is gentle; build the chart together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T10_MATINI_YA_KIDIJITALI.KUSOMA_KIDIJITALI.M5_KID_FOLDER_T10', 'KISW.G5.KUSOMA.T10_MATINI_YA_KIDIJITALI.KUSOMA_KIDIJITALI', 'Mixes up a folder and a file: looks for the passage on the screen without opening the folder it is in.', '{"question":"Kifungu \"Itikadi Potovu\" kimehifadhiwa ndani ya folda \"Kiswahili\". Utakifunguaje?","wrong_answer":"bonyeza \"Itikadi Potovu\" kwenye skrini ya mwanzo","correct_answer":"fungua folda \"Kiswahili\", kisha bonyeza mara mbili faili \"Itikadi Potovu\""}'::jsonb, 'The child has only used apps on a phone, where there are no folders.', 'The question "Kifungu "Itikadi Potovu" kimehifadhiwa ndani ya folda "Kiswahili". Utakifunguaje?" with "bonyeza "Itikadi Potovu" kwenye skrini ya mwanzo" among the options.', 'Show a real folder (a box file) holding papers; then the same on the screen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T10_MATINI_YA_KIDIJITALI.KUSOMA_KIDIJITALI.M5_KID_SEARCH_T10', 'KISW.G5.KUSOMA.T10_MATINI_YA_KIDIJITALI.KUSOMA_KIDIJITALI', 'Types a whole long question, with spelling mistakes, into the search box.', '{"question":"Unatafuta habari kuhusu itikadi za kidini na za kijamii. Utaandika nini kwenye kisanduku cha kutafutia?","wrong_answer":"naomba unipe habari zote kuhusu itikadi za kidini na za kijamii tafadhali","correct_answer":"itikadi potovu watoto hadithi"}'::jsonb, 'The child talks to the search box as to a person.', 'The question "Unatafuta habari kuhusu itikadi za kidini na za kijamii. Utaandika nini kwenye kisanduku cha kutafutia?" with "naomba unipe habari zote kuhusu itikadi za kidini na za kijamii tafadhali" among the options.', 'Underline the two or three words that carry the meaning; search with those; compare the results.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T10_MATINI_YA_KIDIJITALI.KUSOMA_KIDIJITALI.M5_KID_POPUP_T10', 'KISW.G5.KUSOMA.T10_MATINI_YA_KIDIJITALI.KUSOMA_KIDIJITALI', 'Clicks a pop-up or an advert that says he has won a prize.', '{"question":"Ukiwa unasoma, ujumbe unatokea: \"Umeshinda simu! Bonyeza hapa.\" Ufanye nini?","wrong_answer":"bonyeza ili kupokea simu","correct_answer":"usibonyeze; funga ujumbe na umwambie mwalimu au mzazi"}'::jsonb, 'Offers of prizes are exciting and the child does not know they are traps.', 'The question "Ukiwa unasoma, ujumbe unatokea: "Umeshinda simu! Bonyeza hapa." Ufanye nini?" with "bonyeza ili kupokea simu" among the options.', 'Show two screenshots, one real page and one trap; the child finds three signs of the trap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T10_MATINI_YA_KIDIJITALI.KUSOMA_KIDIJITALI.M5_KID_SITE_T10', 'KISW.G5.KUSOMA.T10_MATINI_YA_KIDIJITALI.KUSOMA_KIDIJITALI', 'Uses any site that comes up and gives his name, school or phone number when a site asks.', '{"question":"Tovuti inakuuliza jina lako kamili, shule yako na nambari ya simu ya mzazi kabla ya kusoma hadithi. Ufanye nini?","wrong_answer":"jaza ili usome hadithi","correct_answer":"usijaze; tumia tovuti salama aliyokupa mwalimu"}'::jsonb, 'The child wants the story and does not see personal details as worth protecting.', 'The question "Tovuti inakuuliza jina lako kamili, shule yako na nambari ya simu ya mzazi kabla ya kusoma hadithi. Ufanye nini?" with "jaza ili usome hadithi" among the options.', 'List the details that are private; practise saying no to a form.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T10_MATINI_YA_KIDIJITALI.KUSOMA_KIDIJITALI.M5_KID_ORDER_T10', 'KISW.G5.KUSOMA.T10_MATINI_YA_KIDIJITALI.KUSOMA_KIDIJITALI', 'Puts the steps of finding and reading a passage in the wrong order (reads before searching, or searches before switching on).', '{"question":"Ni hatua ipi huja kwanza?","wrong_answer":"andika maneno ya kutafutia","correct_answer":"washa tarakilishi na ufungue kivinjari"}'::jsonb, 'The child has watched an adult do the steps quickly and remembers the parts, not the order.', 'The question "Ni hatua ipi huja kwanza?" with "andika maneno ya kutafutia" among the options.', 'Step cards: the child orders them, then does them on a real device.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T10_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI.M5_INS_FACTS_T10', 'KISW.G5.KUANDI.T10_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'Writes facts or an explanation where a story of events is asked.', '{"question":"Ni sentensi ipi ni mwanzo wa insha ya masimulizi yenye anwani \"Siku Bibi Alipoacha Imani Potovu\"?","wrong_answer":"Imani potovu ni mawazo yasiyo ya kweli.","correct_answer":"Bibi aliamini kuwa paka mweusi huleta mkosi."}'::jsonb, 'The child knows a lot about the topic and writes what he knows instead of telling what happened.', 'The question "Ni sentensi ipi ni mwanzo wa insha ya masimulizi yenye anwani "Siku Bibi Alipoacha Imani Potovu"?" with "Imani potovu ni mawazo yasiyo ya kweli." among the options.', 'Ask: who, where, what happened first, then, in the end? A story answers these; an explanation does not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T10_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI.M5_INS_TENSE_T10', 'KISW.G5.KUANDI.T10_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'Tells a past story in the present tense (-na-), or mixes -na- and -li- in one story.', '{"question":"Ni sentensi ipi inafaa katika masimulizi ya jambo lililotokea jana: \"Siku Bibi Alipoacha Imani Potovu\"?","wrong_answer":"Bibi anaamini kuwa paka mweusi huleta mkosi.","correct_answer":"Bibi aliamini kuwa paka mweusi huleta mkosi."}'::jsonb, 'The child writes as he speaks while remembering, and English stories in class are told in the present too.', 'The question "Ni sentensi ipi inafaa katika masimulizi ya jambo lililotokea jana: "Siku Bibi Alipoacha Imani Potovu"?" with "Bibi anaamini kuwa paka mweusi huleta mkosi." among the options.', 'Circle every verb; check its tense marker against the time words (jana, siku moja).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T10_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI.M5_INS_ORDER_T10', 'KISW.G5.KUANDI.T10_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'Puts the events in an order that cannot have happened (the end before the start), with no linking words.', '{"question":"Ni mpangilio upi wa matukio unafaa katika insha \"Siku Bibi Alipoacha Imani Potovu\"?","wrong_answer":"bibi alimfuga paka, bibi alielewa, mwalimu alieleza ukweli, bibi aliogopa paka","correct_answer":"bibi aliogopa paka, mwalimu alieleza ukweli, bibi alielewa, bibi alimfuga paka"}'::jsonb, 'The child writes events as they come to mind; nobody has asked for a plan first.', 'The question "Ni mpangilio upi wa matukio unafaa katika insha "Siku Bibi Alipoacha Imani Potovu"?" with "bibi alimfuga paka, bibi alielewa, mwalimu alieleza ukweli, bibi aliogopa paka" among the options.', 'Plan with three boxes (mwanzo, kati, mwisho) and linking words (kwanza, kisha, hatimaye) before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T10_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI.M5_INS_END_T10', 'KISW.G5.KUANDI.T10_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'Ends the insha abruptly ("Mwisho." or "The end") with no closing paragraph (hitimisho).', '{"question":"Ni ipi ni hitimisho bora la insha \"Siku Bibi Alipoacha Imani Potovu\"?","wrong_answer":"Mwisho.","correct_answer":"Tangu siku hiyo, nimejifunza kuwa mwangalifu kila wakati."}'::jsonb, 'Storybooks for young readers end with "Mwisho" and the child copies that.', 'The question "Ni ipi ni hitimisho bora la insha "Siku Bibi Alipoacha Imani Potovu"?" with "Mwisho." among the options.', 'Show three endings; the child picks the one that closes the main idea or the lesson.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T10_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI.M5_INS_MIX_T10', 'KISW.G5.KUANDI.T10_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'Puts English or Sheng words in the insha (tulienda kwa party, mathe, form).', '{"question":"Ni sentensi ipi imeandikwa kwa Kiswahili sanifu?","wrong_answer":"Mathe alinipea form ya kujaza.","correct_answer":"Mama alinipa fomu ya kujaza."}'::jsonb, 'The child speaks a mixed language at home and with friends and does not notice the switch in writing.', 'The question "Ni sentensi ipi imeandikwa kwa Kiswahili sanifu?" with "Mathe alinipea form ya kujaza." among the options.', 'Underline each non-Kiswahili word; find the Kiswahili word together (mama, sherehe, fomu).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T10_NYAKATI_NA_HALI.MAZOEA_TIMILIFU.M_NYK_HU_SUBJECT', 'KISW.G5.SARUFI.T10_NYAKATI_NA_HALI.MAZOEA_TIMILIFU', 'Adds a subject prefix to hu- (anahunywa, huanasoma).', '{"question":"Kila asubuhi Juma ___ maji.","wrong_answer":"anahunywa","correct_answer":"hunywa"}'::jsonb, 'The child thinks every verb must have a person prefix.', 'A gap for hali ya mazoea with prefixed forms.', 'Say "Juma hunywa maji" aloud: does hu- already stand for the person?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T10_NYAKATI_NA_HALI.MAZOEA_TIMILIFU.M_NYK_ME_PAST', 'KISW.G5.SARUFI.T10_NYAKATI_NA_HALI.MAZOEA_TIMILIFU', 'Uses -li- (past) where the action is complete and is still true now (-me-).', '{"question":"Mama ___ kupika chakula (sasa kiko tayari).","wrong_answer":"alimaliza","correct_answer":"amemaliza"}'::jsonb, 'The child treats -me- and -li- as the same: both mean "past".', 'A gap where the action is finished but still matters now.', 'Ask whether the action is finished now, with a result you can see.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T10_NYAKATI_NA_HALI.MAZOEA_TIMILIFU.M_NYK_NA_HABIT', 'KISW.G5.SARUFI.T10_NYAKATI_NA_HALI.MAZOEA_TIMILIFU', 'Uses -na- (now) for what is done every day.', '{"question":"Kila Jumamosi Wanjiru ___ nguo.","wrong_answer":"anafua","correct_answer":"hufua"}'::jsonb, 'The child thinks every action that happens "now" is -na-.', 'A gap for something done every week.', 'Does it happen every time, or only now?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T10_NYAKATI_NA_HALI.MAZOEA_TIMILIFU.M5_NYK_ME_FUTURE', 'KISW.G5.SARUFI.T10_NYAKATI_NA_HALI.MAZOEA_TIMILIFU', 'Uses -me- for something that has not happened yet (kesho nimemaliza).', '{"question":"Jaza: Kesho saa nne ___ (maliza) kazi.","wrong_answer":"nimemaliza","correct_answer":"nitakuwa nimemaliza"}'::jsonb, '-me- is felt as "done" and the child uses it for any finished action, even in the future.', 'The question "Jaza: Kesho saa nne ___ (maliza) kazi." with "nimemaliza" among the options.', 'Timeline: -me- is finished by now; for "finished by a future time" Kiswahili uses nitakuwa nimemaliza.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T11_MASIMULIZI.MASIMULIZI.M5_MSM_DETAIL_T11', 'KISW.G5.KUSIKI.T11_MASIMULIZI.MASIMULIZI', 'Gives a detail of the narration as its message.', '{"question":"Ulisikiliza masimulizi kuhusu kijana aliyeweka akiba kununua mbuzi. Ujumbe wake ni upi?","wrong_answer":"Kijana alinunua mbuzi wawili.","correct_answer":"Tukiweka akiba na kuwekeza kwa busara, tunajenga maisha bora."}'::jsonb, 'The detail was vivid; the child has not asked what the whole narration teaches.', 'The question "Ulisikiliza masimulizi kuhusu kijana aliyeweka akiba kununua mbuzi. Ujumbe wake ni upi?" with "Kijana alinunua mbuzi wawili." among the options.', 'After listening, ask: what did the speaker want us to learn? Then: what is one thing that happened?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T11_MASIMULIZI.MASIMULIZI.M5_MSM_ORDER_T11', 'KISW.G5.KUSIKI.T11_MASIMULIZI.MASIMULIZI', 'Retells the events in a mixed order, starting with the most exciting part.', '{"question":"Unaposimulia, unaanza na nini?","wrong_answer":"sehemu ya kusisimua zaidi","correct_answer":"mwanzo: nani, wapi, lini"}'::jsonb, 'The child jumps to the part that impressed him most.', 'The question "Unaposimulia, unaanza na nini?" with "sehemu ya kusisimua zaidi" among the options.', 'Retell with three fingers: mwanzo, kati, mwisho.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T11_MASIMULIZI.MASIMULIZI.M5_MSM_GESTURE_T11', 'KISW.G5.KUSIKI.T11_MASIMULIZI.MASIMULIZI', 'Uses gestures or a face that do not match the words (smiles while telling a sad part, stands still for an action).', '{"question":"Unasimulia: \"Mbuzi wake walizaana wakawa wengi sana!\" Ishara ipi inafaa?","wrong_answer":"kushika kichwa kwa huzuni","correct_answer":"kufungua mikono kuonyesha wingi"}'::jsonb, 'The child is nervous and does not link the body to the words.', 'The question "Unasimulia: "Mbuzi wake walizaana wakawa wengi sana!" Ishara ipi inafaa?" with "kushika kichwa kwa huzuni" among the options.', 'Mirror game in pairs: one says a line, the other shows the feeling; swap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T11_MASIMULIZI.MASIMULIZI.M5_MSM_MIX_T11', 'KISW.G5.KUSIKI.T11_MASIMULIZI.MASIMULIZI', 'Mixes English or Sheng into the telling (Then tukaenda..., ilikuwa poa sana).', '{"question":"Ni sentensi ipi inafaa unaposimulia darasani?","wrong_answer":"Then tukaenda home, ilikuwa poa sana.","correct_answer":"Kisha tukaenda nyumbani; ilikuwa siku nzuri sana."}'::jsonb, 'The child narrates as he talks with friends.', 'The question "Ni sentensi ipi inafaa unaposimulia darasani?" with "Then tukaenda home, ilikuwa poa sana." among the options.', 'Record a telling; play it back; the child finds the non-Kiswahili words and replaces them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSIKI.T11_MASIMULIZI.MASIMULIZI.M5_MSM_OFFTOPIC_T11', 'KISW.G5.KUSIKI.T11_MASIMULIZI.MASIMULIZI', 'Tells a story that is not on the topic given (uwekezaji (investment)).', '{"question":"Mada ni uwekezaji (investment). Ni masimulizi yapi yanafaa?","wrong_answer":"Siku nilipotazama mechi ya mpira","correct_answer":"Siku kijana aliyeweka akiba kununua mbuzi"}'::jsonb, 'The child tells the story he knows best, whatever the topic.', 'The question "Mada ni uwekezaji (investment). Ni masimulizi yapi yanafaa?" with "Siku nilipotazama mechi ya mpira" among the options.', 'Write the topic on the board; before telling, the child says in one sentence how his story fits it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M5_UFS_WORDBYWORD_T11', 'KISW.G5.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Wanakijiji walianzisha chama cha kuweka akiba na kukopa.\"?","wrong_answer":"Wanakijiji ... walianzisha ... chama ... cha ... kuweka ... akiba ... na ... kukopa.","correct_answer":"Wanakijiji walianzisha chama cha kuweka akiba na kukopa."}'::jsonb, 'The child is still decoding each word and has not yet learnt to read a phrase as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Wanakijiji walianzisha chama cha kuweka akiba na kukopa."?" with "Wanakijiji ... walianzisha ... chama ... cha ... kuweka ... akiba ... na ... kukopa." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it as one breath; then phrase-cut the passage with slashes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M5_UFS_RACE_T11', 'KISW.G5.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Ni kasi ipi ifaayo ya kusoma kifungu darasani?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, ili kila neno lisikike"}'::jsonb, 'Reading races in class reward speed; the child has not been asked whether listeners understood.', 'The question "Ni kasi ipi ifaayo ya kusoma kifungu darasani?" with "haraka iwezekanavyo" among the options.', 'Time two readings: one very fast, one at speaking pace; listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M5_UFS_FLAT_T11', 'KISW.G5.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads a question and an exclamation in the same flat voice as a statement.', '{"question":"Sentensi \"Je, unajua faida ya kuweka akiba?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the mark at the end.', 'The question "Sentensi "Je, unajua faida ya kuweka akiba?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that matches each reading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M5_UFS_NOPAUSE_T11', 'KISW.G5.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads on through the koma and the kikomo without a pause.', '{"question":"Unasoma: \"Ajabu, biashara yake imestawi sana!\" Unasimama wapi kidogo?","wrong_answer":"hapana mahali, unasoma moja kwa moja","correct_answer":"kwenye koma na kwenye kikomo au alama ya hisi"}'::jsonb, 'The marks are read as decoration; the child has not linked them to breath.', 'The question "Unasoma: "Ajabu, biashara yake imestawi sana!" Unasimama wapi kidogo?" with "hapana mahali, unasoma moja kwa moja" among the options.', 'Clap once at a koma, twice at a kikomo while reading together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M5_UFS_SOUND_T11', 'KISW.G5.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Says /l/ for /r/ or /r/ for /l/ while reading (faida read as faita).', '{"question":"Neno \"faida\" linatamkwa vipi?","wrong_answer":"faita","correct_answer":"faida"}'::jsonb, 'The first language of the child does not separate these sounds, so the reading carries the home sound.', 'The question "Neno "faida" linatamkwa vipi?" with "faita" among the options.', 'Make a list of the passage words with the hard sound; practise them before reading the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T11_BARUAPEPE.KUANDIKA_BARUAPEPE.M5_INS_NOSUBJ_T11', 'KISW.G5.KUANDI.T11_BARUAPEPE.KUANDIKA_BARUAPEPE', 'Leaves the subject box empty or writes the whole message in it.', '{"question":"Katika baruapepe, kisanduku cha \"Kichwa\" kinaandikwa nini?","wrong_answer":"ujumbe wote","correct_answer":"maneno machache yanayotaja ujumbe, kama \"Mpango wa Kuweka Akiba\""}'::jsonb, 'The child has used chat apps that have no subject line.', 'The question "Katika baruapepe, kisanduku cha "Kichwa" kinaandikwa nini?" with "ujumbe wote" among the options.', 'Show an inbox: the subject is all the reader sees before opening.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T11_BARUAPEPE.KUANDIKA_BARUAPEPE.M5_INS_ADDR_T11', 'KISW.G5.KUANDI.T11_BARUAPEPE.KUANDIKA_BARUAPEPE', 'Writes a postal address and a date at the top, as in a paper letter.', '{"question":"Baruapepe huanza vipi?","wrong_answer":"S.L.P. 120, Nakuru, na tarehe juu kulia","correct_answer":"salamu kwa mpokeaji, kama \"Habari Amina,\""}'::jsonb, 'The paper letter is the model the child knows.', 'The question "Baruapepe huanza vipi?" with "S.L.P. 120, Nakuru, na tarehe juu kulia" among the options.', 'Compare a paper letter and an email; the email programme adds the address and date.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T11_BARUAPEPE.KUANDIKA_BARUAPEPE.M5_INS_TOFIELD_T11', 'KISW.G5.KUANDI.T11_BARUAPEPE.KUANDIKA_BARUAPEPE', 'Puts the receiver''s name, not the email address, in the "Kwa" box.', '{"question":"Kisanduku cha \"Kwa\" kinaandikwa nini?","wrong_answer":"Amina Otieno","correct_answer":"amina.otieno@mfano.co.ke"}'::jsonb, 'The child writes the person as on an envelope.', 'The question "Kisanduku cha "Kwa" kinaandikwa nini?" with "Amina Otieno" among the options.', 'Show what an email address looks like (jina@mahali); practise reading it aloud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.KUANDI.T11_BARUAPEPE.KUANDIKA_BARUAPEPE.M5_INS_TEXTSPEAK_T11', 'KISW.G5.KUANDI.T11_BARUAPEPE.KUANDIKA_BARUAPEPE', 'Writes in short chat forms (sawa, poa, nkt, 2moro) and no closing.', '{"question":"Ni sentensi ipi inafaa katika baruapepe?","wrong_answer":"Poa, tutaonana 2moro.","correct_answer":"Asante. Tutaonana kesho."}'::jsonb, 'Chat habits come into the email.', 'The question "Ni sentensi ipi inafaa katika baruapepe?" with "Poa, tutaonana 2moro." among the options.', 'Rewrite one chat message as a short email with a greeting and a closing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T11_UKANUSHAJI.UKANUSHAJI.M_NEG_SI_ONLY', 'KISW.G5.SARUFI.T11_UKANUSHAJI.UKANUSHAJI', 'Makes the negative by putting si or hapana before the verb (si nasoma).', '{"question":"Kanusha: \"Ninasoma kitabu.\"","wrong_answer":"Si ninasoma kitabu.","correct_answer":"Sisomi kitabu."}'::jsonb, 'The child copies English "I do not" or puts a word in front.', 'A negative with si before the verb.', 'Ask whether the verb itself changes its beginning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T11_UKANUSHAJI.UKANUSHAJI.M_NEG_KEEP_TENSE', 'KISW.G5.SARUFI.T11_UKANUSHAJI.UKANUSHAJI', 'Keeps the tense marker (-na-, -me-, -li-) in the negative (hamesoma instead of hajasoma).', '{"question":"Kanusha: \"Amesoma kitabu.\"","wrong_answer":"Hamesoma kitabu.","correct_answer":"Hajasoma kitabu."}'::jsonb, 'The child takes only the person prefix and keeps the rest.', 'A negative in -me- written as hame-.', 'Ask which letters replace -me- in the negative.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T11_UKANUSHAJI.UKANUSHAJI.M_NEG_PERSON', 'KISW.G5.SARUFI.T11_UKANUSHAJI.UKANUSHAJI', 'Keeps the positive person prefix (ni-, tu-, wa-) in the negative.', '{"question":"Kanusha: \"Tutasoma kesho.\"","wrong_answer":"Tusitasoma kesho.","correct_answer":"Hatutasoma kesho."}'::jsonb, 'The child changes the tense but not the person prefix.', 'A negative of tu- written as tu- plus si.', 'Ask what the negative of ninasoma starts with (si-), and of tutasoma (hatu-).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T11_UKANUSHAJI.UKANUSHAJI.M_NEG_KEEP_NA', 'KISW.G5.SARUFI.T11_UKANUSHAJI.UKANUSHAJI', 'Keeps -na- in the negative present (hasomina, hanasoma).', '{"question":"Kanusha: \"Anasoma kitabu.\"","wrong_answer":"Hanasoma kitabu.","correct_answer":"Hasomi kitabu."}'::jsonb, 'The child drops -na- but not entirely; present negative has no tense marker.', 'A negative present with -na- kept.', 'Say the negative aloud: does it have -na-?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T11_UKANUSHAJI.UKANUSHAJI.M_NEG_WRONG_TENSE', 'KISW.G5.SARUFI.T11_UKANUSHAJI.UKANUSHAJI', 'Gives the negative of another tense (hasomi for hajasoma, sikusoma for sisomi).', '{"question":"Kanusha: \"Amesoma kitabu.\"","wrong_answer":"Hasomi kitabu.","correct_answer":"Hajasoma kitabu."}'::jsonb, 'The child makes a correct negative but of the wrong tense.', 'A negative of a different tense among the options.', 'Ask which tense the positive sentence is in, and which negative marks it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.UKUBWA_M.M_UKM_SWAP', 'KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.UKUBWA_M', 'Swaps the big form (ji-) and the small form (ki-).', '{"question":"Udogo wa \"mtoto\" ni ___.","wrong_answer":"jitoto","correct_answer":"kitoto"}'::jsonb, 'The child learned both prefixes but not which means big and which small.', 'Questions that ask for big and for small.', 'Ki- is the prefix of kijiji, kitoto, kijiko: small things.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.UKUBWA_M.M_UKM_KEEP_M', 'KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.UKUBWA_M', 'Keeps the m- (jimtoto, kimtoto) when the new prefix goes on.', '{"question":"Ukubwa wa \"mtoto\" ni ___.","wrong_answer":"jimtoto","correct_answer":"jitoto"}'::jsonb, 'The child adds the prefix to the whole word.', 'A gap where m- is left on.', 'Take away the m- of mtoto, then add ji-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.UKUBWA_M.M_UKM_ONE_SYLLABLE', 'KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.UKUBWA_M', 'Does not add ji- to a noun with one-syllable root (mti, mto, mji) when making the small form (kimti, kimto).', '{"question":"Udogo wa \"mji\" ni ___.","wrong_answer":"kimji","correct_answer":"kijiji"}'::jsonb, 'The child uses the rule for longer roots.', 'Small forms of mji, mto, mti.', 'Say the word kijiji aloud: where is the ji?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.UKUBWA_M.M5_UKM_AGREE', 'KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.UKUBWA_M', 'Gives the big or small form but keeps the agreement of the ordinary noun (jitoto analia for jitoto linalia).', '{"question":"Jaza: Kitoto ___ (kinalia / analia).","wrong_answer":"analia","correct_answer":"kinalia"}'::jsonb, 'The child changes the noun and keeps the person agreement.', 'The question "Jaza: Kitoto ___ (kinalia / analia)." with "analia" among the options.', 'The big form takes LI-YA (jitoto linalia), the small form KI-VI (kitoto kinalia).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.UKUBWA_N.M_UKN_KEEP_N', 'KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.UKUBWA_N', 'Keeps the n- or ny- of the noun (jinyumba, kinyumba).', '{"question":"Ukubwa wa \"nyumba\" ni ___.","wrong_answer":"jinyumba","correct_answer":"jumba"}'::jsonb, 'The child does not drop the first sound as with m- nouns.', 'A gap where the first sound is kept.', 'Say "jumba la ghorofa", not "jinyumba".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.UKUBWA_N.M_UKN_SWAP', 'KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.UKUBWA_N', 'Swaps ji-/ju- (big) and ki- (small) for n- nouns.', '{"question":"Udogo wa \"nyumba\" ni ___.","wrong_answer":"jumba","correct_answer":"kijumba"}'::jsonb, 'Two prefixes and two meanings, learned together.', 'Big and small forms asked in turn.', 'Ki- is small: kijumba is a hut.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.UKUBWA_N.M5_UKN_JU', 'KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.UKUBWA_N', 'Uses ji- where ju- is needed for an n- noun with a root starting with a vowel or after ny- (nyumba -> jumba).', '{"question":"Ukubwa wa \"nyumba\" ni?","wrong_answer":"jinyumba","correct_answer":"jumba"}'::jsonb, 'ji- is the big prefix learnt with m- nouns; the n-/ny- is kept.', 'The question "Ukubwa wa "nyumba" ni?" with "jinyumba" among the options.', 'Drop n- or ny-, then add ji- (or ju- before -mba: jumba); compare with the dictionary.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.UKUBWA_N.M5_UKN_AGREE', 'KISW.G5.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.UKUBWA_N', 'Keeps the I-ZI agreement for the big form (jumba imejengwa for jumba limejengwa).', '{"question":"Jaza: Jumba ___ (limejengwa / imejengwa).","wrong_answer":"imejengwa","correct_answer":"limejengwa"}'::jsonb, 'The child changes the noun and keeps the I-ZI prefix of nyumba.', 'The question "Jaza: Jumba ___ (limejengwa / imejengwa)." with "imejengwa" among the options.', 'The big form moves to LI-YA: jumba li-, majumba ya-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
